  2→import React, { useState, useRef, useEffect } from 'react';
  3→import { motion } from 'framer-motion';
  4→import { RefreshCw, Copy, Check, FileText, ChevronLeft, FileType, Share2, Upload, History as HistoryIcon, Clock, Wrench, Home, Banknote, ShieldCheck, UserCheck, Package, Pen, ArrowRight, Send } from 'lucide-react';
  5→import { LoadingSpinner } from '../components/GlassComponents';
  6→import { generateSmartTemplate, adaptContractTemplate, generateContractQuestions, generateContractFromAnswers, editContract } from '../services/geminiService';
  7→import ReactMarkdown from 'react-markdown';
  8→import { ViewProps, HistoryItem, ContractQuestion } from '../types';
  9→import { useToast } from '../components/Toast';
 10→import { saveToHistory, subscribeToHistory } from '../services/historyService';
 11→import { t } from '../services/translations';
 12→
 13→type Step = 'catalog' | 'custom' | 'questions' | 'generating' | 'result';
 14→
 15→const CONTRACT_TYPES = [
 16→  { id: 'services', icon: Wrench, titleKey: 'contract_type_services', descKey: 'contract_type_services_desc', color: 'text-blue-500', bg: 'bg-blue-50' },
 17→  { id: 'rental', icon: Home, titleKey: 'contract_type_rental', descKey: 'contract_type_rental_desc', color: 'text-emerald-500', bg: 'bg-emerald-50' },
 18→  { id: 'loan', icon: Banknote, titleKey: 'contract_type_loan', descKey: 'contract_type_loan_desc', color: 'text-amber-500', bg: 'bg-amber-50' },
 19→  { id: 'nda', icon: ShieldCheck, titleKey: 'contract_type_nda', descKey: 'contract_type_nda_desc', color: 'text-violet-500', bg: 'bg-violet-50' },
 20→  { id: 'employment', icon: UserCheck, titleKey: 'contract_type_employment', descKey: 'contract_type_employment_desc', color: 'text-rose-500', bg: 'bg-rose-50' },
 21→  { id: 'supply', icon: Package, titleKey: 'contract_type_supply', descKey: 'contract_type_supply_desc', color: 'text-cyan-500', bg: 'bg-cyan-50' },
 22→];
 23→
 24→export const ContractView: React.FC<ViewProps> = ({ user, onBack, initialPrompt, language = 'ru' }) => {
 25→  const { showToast } = useToast();
 26→  const [step, setStep] = useState<Step>('catalog');
 27→  const [selectedType, setSelectedType] = useState<string>('');
 28→
 29→  // Questions step
 30→  const [questions, setQuestions] = useState<ContractQuestion[]>([]);
 31→  const [answers, setAnswers] = useState<Record<number, string>>({});
 32→  const [loadingQuestions, setLoadingQuestions] = useState(false);
 33→
 34→  // Custom / free text
 35→  const [description, setDescription] = useState(initialPrompt || '');
 36→
 37→  // Template mode
 38→  const [templateFileBase64, setTemplateFileBase64] = useState<string | null>(null);
 39→  const [templateType, setTemplateType] = useState<'text' | 'image' | null>(null);
 40→  const [adaptationPrompt, setAdaptationPrompt] = useState('');
 41→
 42→  // Result
 43→  const [result, setResult] = useState<string>('');
 44→  const [editText, setEditText] = useState('');
 45→  const [isEditing, setIsEditing] = useState(false);
 46→
 47→  // History
 48→  const [history, setHistory] = useState<HistoryItem[]>([]);
 49→  const [copied, setCopied] = useState(false);
 50→
 51→  const scrollRef = useRef<HTMLDivElement>(null);
 52→  const fileInputRef = useRef<HTMLInputElement>(null);
 53→
 54→  useEffect(() => {
 55→    if (user?.id) {
 56→      const unsubscribe = subscribeToHistory(user.id, 'contract', (items) => {
 57→        setHistory(items);
 58→      });
 59→      return () => unsubscribe();
 60→    }
 61→  }, [user?.id]);
 62→
 63→  // Handle initialPrompt — go straight to generation
 64→  useEffect(() => {
 65→    if (initialPrompt && initialPrompt.length > 5 && step === 'catalog') {
 66→      setDescription(initialPrompt);
 67→      handleGenerateFromText(initialPrompt);
 68→    }
 69→  }, [initialPrompt]);
 70→
 71→  const handleInputFocus = (e: React.FocusEvent<HTMLTextAreaElement | HTMLInputElement>) => {
 72→    setTimeout(() => {
 73→      e.target.scrollIntoView({ behavior: 'smooth', block: 'center' });
 74→    }, 300);
 75→  };
 76→
 77→  // User selects a type from catalog
 78→  const handleSelectType = async (typeId: string) => {
 79→    setSelectedType(typeId);
 80→    setLoadingQuestions(true);
 81→    setStep('questions');
 82→    setAnswers({});
 83→
 84→    const typeName = t(`contract_type_${typeId}`, language);
 85→    const qs = await generateContractQuestions(typeName, language);
 86→
 87→    if (qs.length > 0) {
 88→      setQuestions(qs);
 89→    } else {
 90→      // Fallback: go to custom text mode
 91→      showToast(t('error_generation', language), 'error');
 92→      setStep('catalog');
 93→    }
 94→    setLoadingQuestions(false);
 95→  };
 96→
 97→  // Generate from structured answers
 98→  const handleGenerateFromAnswers = async () => {
 99→    const filledAnswers = questions
100→      .map((q, i) => ({ question: q.question, answer: answers[i] || '' }))
101→      .filter(a => a.answer.trim());
102→
103→    if (filledAnswers.length === 0) {
104→      showToast(t('error_generation', language), 'warning');
105→      return;
106→    }
107→
108→    setStep('generating');
109→    const typeName = t(`contract_type_${selectedType}`, language);
110→
111→    const minTime = new Promise(resolve => setTimeout(resolve, 1500));
112→    const genPromise = generateContractFromAnswers(typeName, filledAnswers, language);
113→    const [contract] = await Promise.all([genPromise, minTime]);
114→
115→    if (contract) {
116→      setResult(contract);
117→      setStep('result');
118→      saveResult(contract, filledAnswers.map(a => `${a.question}: ${a.answer}`).join('; '));
119→    } else {
120→      showToast(t('error_generation', language), 'error');
121→      setStep('questions');
122→    }
123→  };
124→
125→  // Generate from free text description
126→  const handleGenerateFromText = async (text?: string) => {
127→    const desc = text || description;
128→    if (!desc.trim()) return;
129→
130→    setStep('generating');
131→    const minTime = new Promise(resolve => setTimeout(resolve, 1500));
132→    const genPromise = generateSmartTemplate(desc);
133→    const [template] = await Promise.all([genPromise, minTime]);
134→
135→    if (template) {
136→      setResult(template);
137→      setStep('result');
138→      saveResult(template, desc);
139→    } else {
140→      showToast(t('error_generation', language), 'error');
141→      setStep('custom');
142→    }
143→  };
144→
145→  // Generate from uploaded template
146→  const handleGenerateFromTemplate = async () => {
147→    if (!templateFileBase64 && !description.trim()) return;
148→    if (!adaptationPrompt.trim()) {
149→      showToast(t('contract_placeholder_adapt', language), 'warning');
150→      return;
151→    }
152→
153→    setStep('generating');
154→    const context = templateFileBase64 || description;
155→    const isImg = templateType === 'image';
156→    const adapted = await adaptContractTemplate(context, adaptationPrompt, isImg);
157→
158→    if (adapted) {
159→      setResult(adapted);
160→      setStep('result');
161→      saveResult(adapted, adaptationPrompt);
162→    } else {
163→      showToast(t('error_generation', language), 'error');
164→      setStep('catalog');
165→    }
166→  };
167→
168→  // Edit existing contract
169→  const handleEdit = async () => {
170→    if (!editText.trim() || !result) return;
171→    setIsEditing(true);
172→
173→    const edited = await editContract(result, editText, language);
174→    if (edited) {
175→      setResult(edited);
176→      setEditText('');
177→      saveResult(edited, editText);
178→      showToast('Done', 'success');
179→    } else {
180→      showToast(t('error_generation', language), 'error');
181→    }
182→    setIsEditing(false);
183→  };
184→
185→  const saveResult = (content: string, prompt?: string) => {
186→    if (user?.id) {
187→      saveToHistory(user.id, {
188→        type: 'contract',
189→        prompt: prompt || description || selectedType,
190→        content: content
191→      });
192→    }
193→  };
194→
195→  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
196→    const file = e.target.files?.[0];
197→    if (!file) return;
198→    const reader = new FileReader();
199→    reader.onloadend = () => {
200→      const res = reader.result as string;
201→      if (file.type.startsWith('image/')) {
202→        setTemplateType('image');
203→        setTemplateFileBase64(res.split(',')[1]);
204→      } else if (file.type === 'text/plain') {
205→        setTemplateType('text');
206→        setTemplateFileBase64(res);
207→      } else {
208→        setTemplateFileBase64(res.split(',')[1]);
209→        setTemplateType('image');
210→      }
211→    };
212→    if (file.type.startsWith('image/')) {
213→      reader.readAsDataURL(file);
214→    } else {
215→      reader.readAsText(file);
216→    }
217→  };
218→
219→  const handleDownloadWord = () => {
220→    if (!result) return;
221→    const htmlContent = result
222→      .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
223→      .replace(/# (.*?)\n/g, '<h1>$1</h1>')
224→      .replace(/## (.*?)\n/g, '<h2>$1</h2>')
225→      .replace(/\n/g, '<br/>');
226→    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Contract</title></head><body>";
227→    const footer = "</body></html>";
228→    const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(header + htmlContent + footer);
229→    const link = document.createElement("a");
230→    document.body.appendChild(link);
231→    link.href = source;
232→    link.download = `contract_x5_${Date.now()}.doc`;
233→    link.click();
234→    document.body.removeChild(link);
235→  };
236→
237→  const handleRestore = (item: HistoryItem) => {
238→    if (item.content) {
239→      setResult(item.content);
240→      setStep('result');
241→      if (item.prompt) setDescription(item.prompt);
242→      if (scrollRef.current) scrollRef.current.scrollTop = 0;
243→    }
244→  };
245→
246→  const handleReset = () => {
247→    setStep('catalog');
248→    setDescription('');
249→    setResult('');
250→    setEditText('');
251→    setSelectedType('');
252→    setQuestions([]);
253→    setAnswers({});
254→    setTemplateFileBase64(null);
255→    setAdaptationPrompt('');
256→  };
257→
258→  // Check if at least one required answer is filled
259→  const hasRequiredAnswers = questions.some((q, i) => q.required && answers[i]?.trim());
260→
261→  return (
262→    <div className="flex flex-col h-full overflow-hidden animate-fade-in relative px-6 pt-16 pb-0">
263→
264→      {/* Header */}
265→      <div className="flex items-center justify-between mb-6 shrink-0 z-20">
266→        <div className="flex items-center gap-3">
267→          <button
268→            onClick={step === 'catalog' ? onBack : step === 'questions' ? () => setStep('catalog') : step === 'custom' ? () => setStep('catalog') : onBack}
269→            className="w-10 h-10 glass-card rounded-full flex items-center justify-center active:scale-95 transition-transform hover:bg-slate-100"
270→          >
271→            <ChevronLeft className="text-slate-900" size={22} />
272→          </button>
273→          <div>
274→            <h2 className="text-xl font-extrabold text-slate-900 tracking-tight leading-none">{t('contract_title', language)}</h2>
275→            <p className="text-xs text-slate-500 font-medium mt-0.5">{t('contract_subtitle', language)}</p>
276→          </div>
277→        </div>
278→      </div>
279→
280→      <div ref={scrollRef} className="flex-1 overflow-y-auto pb-32 scroll-smooth no-scrollbar z-10">
281→
282→        {/* =========== STEP 1: CATALOG =========== */}
283→        {step === 'catalog' && (
284→          <div className="space-y-5 animate-slide-up">
285→
286→            {/* Section title */}
287→            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">
288→              {t('contract_choose_type', language)}
289→            </p>
290→
291→            {/* Type Grid */}
292→            <div className="grid grid-cols-2 gap-3">
293→              {CONTRACT_TYPES.map((type, idx) => (
294→                <motion.button
295→                  key={type.id}
296→                  initial={{ opacity: 0, y: 20 }}
297→                  animate={{ opacity: 1, y: 0 }}
298→                  transition={{ delay: 0.05 * idx }}
299→                  whileTap={{ scale: 0.95 }}
300→                  onClick={() => handleSelectType(type.id)}
301→                  className="bg-white p-4 rounded-[24px] border border-slate-100 shadow-sm text-left flex flex-col gap-3 active:bg-slate-50 transition-colors"
302→                >
303→                  <div className={`w-11 h-11 ${type.bg} rounded-2xl flex items-center justify-center`}>
304→                    <type.icon size={22} className={type.color} />
305→                  </div>
306→                  <div>
307→                    <p className="text-[15px] font-bold text-slate-900 leading-tight">{t(type.titleKey, language)}</p>
308→                    <p className="text-[11px] text-slate-400 mt-0.5 leading-snug">{t(type.descKey, language)}</p>
309→                  </div>
310→                </motion.button>
311→              ))}
312→            </div>
313→
314→            {/* Custom text option */}
315→            <motion.button
316→              initial={{ opacity: 0, y: 20 }}
317→              animate={{ opacity: 1, y: 0 }}
318→              transition={{ delay: 0.35 }}
319→              whileTap={{ scale: 0.97 }}
320→              onClick={() => setStep('custom')}
321→              className="w-full bg-white p-4 rounded-[24px] border border-slate-100 shadow-sm flex items-center gap-4 active:bg-slate-50 transition-colors"
322→            >
323→              <div className="w-11 h-11 bg-slate-100 rounded-2xl flex items-center justify-center">
324→                <Pen size={20} className="text-slate-500" />
325→              </div>
326→              <div className="text-left flex-1">
327→                <p className="text-[15px] font-bold text-slate-900">{t('contract_custom', language)}</p>
328→                <p className="text-[11px] text-slate-400 mt-0.5">{t('contract_custom_desc', language)}</p>
329→              </div>
330→              <ArrowRight size={18} className="text-slate-300" />
331→            </motion.button>
332→
333→            {/* Upload template */}
334→            <motion.div
335→              initial={{ opacity: 0, y: 20 }}
336→              animate={{ opacity: 1, y: 0 }}
337→              transition={{ delay: 0.4 }}
338→            >
339→              <div
340→                onClick={() => fileInputRef.current?.click()}
341→                className={`w-full p-4 rounded-[24px] border-2 border-dashed flex items-center gap-4 cursor-pointer transition-colors ${templateFileBase64 ? 'border-green-400 bg-green-50' : 'border-slate-200 hover:border-blue-400 bg-white/50'}`}
342→              >
343→                <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.txt" onChange={handleFileUpload} />
344→
345→                {templateFileBase64 ? (
346→                  <>
347→                    <div className="w-11 h-11 bg-green-100 rounded-2xl flex items-center justify-center">
348→                      <Check size={20} className="text-green-600" />
349→                    </div>
350→                    <div className="text-left flex-1">
351→                      <p className="text-[15px] font-bold text-green-700">Uploaded</p>
352→                      <p className="text-[11px] text-green-600 mt-0.5">{templateType === 'image' ? 'Image' : 'Text'}</p>
353→                    </div>
354→                  </>
355→                ) : (
356→                  <>
357→                    <div className="w-11 h-11 bg-slate-50 rounded-2xl flex items-center justify-center">
358→                      <Upload size={20} className="text-slate-400" />
359→                    </div>
360→                    <div className="text-left flex-1">
361→                      <p className="text-[15px] font-bold text-slate-500">{t('contract_upload', language)}</p>
362→                      <p className="text-[11px] text-slate-400 mt-0.5">{t('contract_upload_desc', language)}</p>
363→                    </div>
364→                  </>
365→                )}
366→              </div>
367→
368→              {/* Adaptation prompt (shown when file uploaded) */}
369→              {templateFileBase64 && (
370→                <div className="mt-3 space-y-3">
371→                  <div className="glass-card p-4 rounded-[24px] bg-white border border-slate-100">
372→                    <textarea
373→                      value={adaptationPrompt}
374→                      onChange={(e) => setAdaptationPrompt(e.target.value)}
375→                      onFocus={handleInputFocus}
376→                      placeholder={t('contract_placeholder_adapt', language)}
377→                      className="w-full h-28 bg-slate-50 rounded-[16px] p-4 text-sm font-medium text-slate-900 focus:outline-none resize-none"
378→                    />
379→                  </div>
380→                  <button
381→                    onClick={handleGenerateFromTemplate}
382→                    disabled={!adaptationPrompt.trim()}
383→                    className={`w-full py-5 rounded-[26px] shadow-xl flex items-center justify-center gap-2 text-[17px] font-bold transition-all border border-white/50 ${!adaptationPrompt.trim() ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white'}`}
384→                  >
385→                    <span>{t('contract_btn_fill', language)}</span>
386→                    <FileText size={20} className="opacity-60" />
387→                  </button>
388→                </div>
389→              )}
390→            </motion.div>
391→
392→            {/* History */}
393→            {history.length > 0 && (
394→              <div className="mt-8">
395→                <div className="flex items-center gap-2 mb-4 px-1">
396→                  <HistoryIcon size={16} className="text-slate-400" />
397→                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">History</h3>
398→                </div>
399→                <div className="space-y-3">
400→                  {history.map((item) => (
401→                    <div
402→                      key={item.id}
403→                      onClick={() => handleRestore(item)}
404→                      className="bg-white p-4 rounded-[20px] border border-slate-100 shadow-sm flex items-start gap-3 active:scale-[0.98] transition-all cursor-pointer group"
405→                    >
406→                      <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center text-slate-400 group-hover:bg-slate-900 group-hover:text-white transition-colors shrink-0">
407→                        <FileText size={18} />
408→                      </div>
409→                      <div className="flex-1 min-w-0">
410→                        <p className="text-sm font-bold text-slate-900 line-clamp-2 leading-tight mb-1">
411→                          {item.prompt || "Untitled"}
412→                        </p>
413→                        <div className="flex items-center gap-2 text-[10px] text-slate-400">
414→                          <Clock size={10} />
415→                          <span>{item.createdAt ? new Date(item.createdAt).toLocaleDateString() : 'Recent'}</span>
416→                        </div>
417→                      </div>
418→                    </div>
419→                  ))}
420→                </div>
421→              </div>
422→            )}
423→          </div>
424→        )}
425→
426→        {/* =========== STEP: CUSTOM (free text) =========== */}
427→        {step === 'custom' && (
428→          <div className="space-y-5 animate-slide-up">
429→            <div className="glass-card p-1 rounded-[32px] shadow-2xl shadow-blue-900/5 border border-slate-100 relative bg-white/60">
430→              <textarea
431→                value={description}
432→                onChange={(e) => setDescription(e.target.value)}
433→                onFocus={handleInputFocus}
434→                placeholder={t('contract_placeholder_create', language)}
435→                className="w-full h-48 bg-transparent rounded-[30px] pt-6 pb-4 px-5 text-[17px] font-medium text-slate-900 placeholder-slate-400 focus:outline-none resize-none leading-relaxed"
436→                autoFocus
437→              />
438→            </div>
439→
440→            <button
441→              onClick={() => handleGenerateFromText()}
442→              disabled={!description.trim()}
443→              className={`w-full py-5 rounded-[26px] shadow-xl flex items-center justify-center gap-2 text-[17px] font-bold transition-all border border-white/50 ${!description.trim() ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white shadow-purple-900/20'}`}
444→            >
445→              <span>{t('contract_btn_create', language)}</span>
446→              <FileText size={20} className="opacity-60" />
447→            </button>
448→          </div>
449→        )}
450→
451→        {/* =========== STEP 2: QUESTIONS =========== */}
452→        {step === 'questions' && (
453→          <div className="space-y-5 animate-slide-up">
454→
455→            {/* Selected type badge */}
456→            <div className="flex items-center gap-2 px-1">
457→              <div className={`w-8 h-8 ${CONTRACT_TYPES.find(ct => ct.id === selectedType)?.bg || 'bg-slate-100'} rounded-xl flex items-center justify-center`}>
458→                {(() => {
459→                  const ct = CONTRACT_TYPES.find(c => c.id === selectedType);
460→                  if (ct) {
461→                    const Icon = ct.icon;
462→                    return <Icon size={16} className={ct.color} />;
463→                  }
464→                  return null;
465→                })()}
466→              </div>
467→              <p className="text-[15px] font-bold text-slate-900">{t(`contract_type_${selectedType}`, language)}</p>
468→            </div>
469→
470→            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">
471→              {t('contract_ai_questions', language)}
472→            </p>
473→
474→            {loadingQuestions ? (
475→              <div className="flex flex-col items-center justify-center py-16">
476→                <LoadingSpinner />
477→                <p className="text-sm text-slate-400 mt-4 animate-pulse">{t('contract_ai_questions', language)}</p>
478→              </div>
479→            ) : (
480→              <>
481→                <div className="space-y-4">
482→                  {questions.map((q, idx) => (
483→                    <motion.div
484→                      key={idx}
485→                      initial={{ opacity: 0, y: 15 }}
486→                      animate={{ opacity: 1, y: 0 }}
487→                      transition={{ delay: 0.08 * idx }}
488→                      className="glass-card p-4 rounded-[24px] bg-white border border-slate-100"
489→                    >
490→                      <label className="text-[12px] font-bold text-slate-600 mb-2 block leading-snug">
491→                        {q.question}
492→                        {q.required && <span className="text-rose-400 ml-1">*</span>}
493→                      </label>
494→                      <input
495→                        type="text"
496→                        value={answers[idx] || ''}
497→                        onChange={(e) => setAnswers(prev => ({ ...prev, [idx]: e.target.value }))}
498→                        onFocus={handleInputFocus}
499→                        placeholder={q.placeholder}
500→                        className="w-full bg-slate-50 rounded-[16px] px-4 py-3 text-[15px] font-medium text-slate-900 placeholder-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-200 transition-all"
501→                      />
502→                    </motion.div>
503→                  ))}
504→                </div>
505→
506→                <button
507→                  onClick={handleGenerateFromAnswers}
508→                  disabled={!hasRequiredAnswers}
509→                  className={`w-full py-5 rounded-[26px] shadow-xl flex items-center justify-center gap-2 text-[17px] font-bold transition-all border border-white/50 mt-2 ${!hasRequiredAnswers ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white shadow-purple-900/20'}`}
510→                >
511→                  <span>{t('contract_btn_create', language)}</span>
512→                  <FileText size={20} className="opacity-60" />
513→                </button>
514→              </>
515→            )}
516→          </div>
517→        )}
518→
519→        {/* =========== STEP 3: GENERATING =========== */}
520→        {step === 'generating' && (
