import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { RefreshCw, Copy, Check, FileText, ChevronLeft, FileType, Share2, Upload, History as HistoryIcon, Clock, Wrench, Home, Banknote, ShieldCheck, UserCheck, Package, Pen, ArrowRight, Send } from 'lucide-react';
import { LoadingSpinner } from '../components/GlassComponents';
import { generateSmartTemplate, adaptContractTemplate, generateContractQuestions, generateContractFromAnswers, editContract } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';
import { ViewProps, HistoryItem, ContractQuestion } from '../types';
import { useToast } from '../components/Toast';
import { saveToHistory, subscribeToHistory } from '../services/historyService';
import { t } from '../services/translations';

type Step = 'catalog' | 'custom' | 'questions' | 'generating' | 'result';

const CONTRACT_TYPES = [
  { id: 'services', icon: Wrench, titleKey: 'contract_type_services', descKey: 'contract_type_services_desc', color: 'text-blue-500', bg: 'bg-blue-50' },
  { id: 'rental', icon: Home, titleKey: 'contract_type_rental', descKey: 'contract_type_rental_desc', color: 'text-emerald-500', bg: 'bg-emerald-50' },
  { id: 'loan', icon: Banknote, titleKey: 'contract_type_loan', descKey: 'contract_type_loan_desc', color: 'text-amber-500', bg: 'bg-amber-50' },
  { id: 'nda', icon: ShieldCheck, titleKey: 'contract_type_nda', descKey: 'contract_type_nda_desc', color: 'text-violet-500', bg: 'bg-violet-50' },
  { id: 'employment', icon: UserCheck, titleKey: 'contract_type_employment', descKey: 'contract_type_employment_desc', color: 'text-rose-500', bg: 'bg-rose-50' },
  { id: 'supply', icon: Package, titleKey: 'contract_type_supply', descKey: 'contract_type_supply_desc', color: 'text-cyan-500', bg: 'bg-cyan-50' },
];

export const ContractView: React.FC<ViewProps> = ({ user, onBack, initialPrompt, language = 'ru' }) => {
  const { showToast } = useToast();
  const [step, setStep] = useState<Step>('catalog');
  const [selectedType, setSelectedType] = useState<string>('');

  // Questions step
  const [questions, setQuestions] = useState<ContractQuestion[]>([]);
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [loadingQuestions, setLoadingQuestions] = useState(false);

  // Custom / free text
  const [description, setDescription] = useState(initialPrompt || '');

  // Template mode
  const [templateFileBase64, setTemplateFileBase64] = useState<string | null>(null);
  const [templateType, setTemplateType] = useState<'text' | 'image' | null>(null);
  const [adaptationPrompt, setAdaptationPrompt] = useState('');

  // Result
  const [result, setResult] = useState<string>('');
  const [editText, setEditText] = useState('');
  const [isEditing, setIsEditing] = useState(false);

  // History
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [copied, setCopied] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (user?.id) {
      const unsubscribe = subscribeToHistory(user.id, 'contract', (items) => {
        setHistory(items);
      });
      return () => unsubscribe();
    }
  }, [user?.id]);

  // Handle initialPrompt — go straight to generation
  useEffect(() => {
    if (initialPrompt && initialPrompt.length > 5 && step === 'catalog') {
      setDescription(initialPrompt);
      handleGenerateFromText(initialPrompt);
    }
  }, [initialPrompt]);

  const handleInputFocus = (e: React.FocusEvent<HTMLTextAreaElement | HTMLInputElement>) => {
    setTimeout(() => {
      e.target.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 300);
  };

  // User selects a type from catalog
  const handleSelectType = async (typeId: string) => {
    setSelectedType(typeId);
    setLoadingQuestions(true);
    setStep('questions');
    setAnswers({});

    const typeName = t(`contract_type_${typeId}`, language);
    const qs = await generateContractQuestions(typeName, language);

    if (qs.length > 0) {
      setQuestions(qs);
    } else {
      // Fallback: go to custom text mode
      showToast(t('error_generation', language), 'error');
      setStep('catalog');
    }
    setLoadingQuestions(false);
  };

  // Generate from structured answers
  const handleGenerateFromAnswers = async () => {
    const filledAnswers = questions
      .map((q, i) => ({ question: q.question, answer: answers[i] || '' }))
      .filter(a => a.answer.trim());

    if (filledAnswers.length === 0) {
      showToast(t('error_generation', language), 'warning');
      return;
    }

    setStep('generating');
    const typeName = t(`contract_type_${selectedType}`, language);

    const minTime = new Promise(resolve => setTimeout(resolve, 1500));
    const genPromise = generateContractFromAnswers(typeName, filledAnswers, language);
    const [contract] = await Promise.all([genPromise, minTime]);

    if (contract) {
      setResult(contract);
      setStep('result');
      saveResult(contract, filledAnswers.map(a => `${a.question}: ${a.answer}`).join('; '));
    } else {
      showToast(t('error_generation', language), 'error');
      setStep('questions');
    }
  };

  // Generate from free text description
  const handleGenerateFromText = async (text?: string) => {
    const desc = text || description;
    if (!desc.trim()) return;

    setStep('generating');
    const minTime = new Promise(resolve => setTimeout(resolve, 1500));
    const genPromise = generateSmartTemplate(desc);
    const [template] = await Promise.all([genPromise, minTime]);

    if (template) {
      setResult(template);
      setStep('result');
      saveResult(template, desc);
    } else {
      showToast(t('error_generation', language), 'error');
      setStep('custom');
    }
  };

  // Generate from uploaded template
  const handleGenerateFromTemplate = async () => {
    if (!templateFileBase64 && !description.trim()) return;
    if (!adaptationPrompt.trim()) {
      showToast(t('contract_placeholder_adapt', language), 'warning');
      return;
    }

    setStep('generating');
    const context = templateFileBase64 || description;
    const isImg = templateType === 'image';
    const adapted = await adaptContractTemplate(context, adaptationPrompt, isImg);

    if (adapted) {
      setResult(adapted);
      setStep('result');
      saveResult(adapted, adaptationPrompt);
    } else {
      showToast(t('error_generation', language), 'error');
      setStep('catalog');
    }
  };

  // Edit existing contract
  const handleEdit = async () => {
    if (!editText.trim() || !result) return;
    setIsEditing(true);

    const edited = await editContract(result, editText, language);
    if (edited) {
      setResult(edited);
      setEditText('');
      saveResult(edited, editText);
      showToast('Done', 'success');
    } else {
      showToast(t('error_generation', language), 'error');
    }
    setIsEditing(false);
  };

  const saveResult = (content: string, prompt?: string) => {
    if (user?.id) {
      saveToHistory(user.id, {
        type: 'contract',
        prompt: prompt || description || selectedType,
        content: content
      });
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const res = reader.result as string;
      if (file.type.startsWith('image/')) {
        setTemplateType('image');
        setTemplateFileBase64(res.split(',')[1]);
      } else if (file.type === 'text/plain') {
        setTemplateType('text');
        setTemplateFileBase64(res);
      } else {
        setTemplateFileBase64(res.split(',')[1]);
        setTemplateType('image');
      }
    };
    if (file.type.startsWith('image/')) {
      reader.readAsDataURL(file);
    } else {
      reader.readAsText(file);
    }
  };

  const handleDownloadWord = () => {
    if (!result) return;
    const htmlContent = result
      .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
      .replace(/# (.*?)\n/g, '<h1>$1</h1>')
      .replace(/## (.*?)\n/g, '<h2>$1</h2>')
      .replace(/\n/g, '<br/>');
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Contract</title></head><body>";
    const footer = "</body></html>";
    const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(header + htmlContent + footer);
    const link = document.createElement("a");
    document.body.appendChild(link);
    link.href = source;
    link.download = `contract_x5_${Date.now()}.doc`;
    link.click();
    document.body.removeChild(link);
  };

  const handleRestore = (item: HistoryItem) => {
    if (item.content) {
      setResult(item.content);
      setStep('result');
      if (item.prompt) setDescription(item.prompt);
      if (scrollRef.current) scrollRef.current.scrollTop = 0;
    }
  };

  const handleReset = () => {
    setStep('catalog');
    setDescription('');
    setResult('');
    setEditText('');
    setSelectedType('');
    setQuestions([]);
    setAnswers({});
    setTemplateFileBase64(null);
    setAdaptationPrompt('');
  };

  // Check if at least one required answer is filled
  const hasRequiredAnswers = questions.some((q, i) => q.required && answers[i]?.trim());

  return (
    <div className="flex flex-col h-full overflow-hidden animate-fade-in relative px-6 pt-16 pb-0">

      {/* Header */}
      <div className="flex items-center justify-between mb-6 shrink-0 z-20">
        <div className="flex items-center gap-3">
          <button
            onClick={step === 'catalog' ? onBack : step === 'questions' ? () => setStep('catalog') : step === 'custom' ? () => setStep('catalog') : onBack}
            className="w-10 h-10 glass-card rounded-full flex items-center justify-center active:scale-95 transition-transform hover:bg-slate-100"
          >
            <ChevronLeft className="text-slate-900" size={22} />
          </button>
          <div>
            <h2 className="text-xl font-extrabold text-slate-900 tracking-tight leading-none">{t('contract_title', language)}</h2>
            <p className="text-xs text-slate-500 font-medium mt-0.5">{t('contract_subtitle', language)}</p>
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto pb-32 scroll-smooth no-scrollbar z-10">

        {/* =========== STEP 1: CATALOG =========== */}
        {step === 'catalog' && (
          <div className="space-y-5 animate-slide-up">

            {/* Section title */}
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">
              {t('contract_choose_type', language)}
            </p>

            {/* Type Grid */}
            <div className="grid grid-cols-2 gap-3">
              {CONTRACT_TYPES.map((type, idx) => (
                <motion.button
                  key={type.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.05 * idx }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => handleSelectType(type.id)}
                  className="bg-white p-4 rounded-[24px] border border-slate-100 shadow-sm text-left flex flex-col gap-3 active:bg-slate-50 transition-colors"
                >
                  <div className={`w-11 h-11 ${type.bg} rounded-2xl flex items-center justify-center`}>
                    <type.icon size={22} className={type.color} />
                  </div>
                  <div>
                    <p className="text-[15px] font-bold text-slate-900 leading-tight">{t(type.titleKey, language)}</p>
                    <p className="text-[11px] text-slate-400 mt-0.5 leading-snug">{t(type.descKey, language)}</p>
                  </div>
                </motion.button>
              ))}
            </div>

            {/* Custom text option */}
            <motion.button
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.35 }}
              whileTap={{ scale: 0.97 }}
              onClick={() => setStep('custom')}
              className="w-full bg-white p-4 rounded-[24px] border border-slate-100 shadow-sm flex items-center gap-4 active:bg-slate-50 transition-colors"
            >
              <div className="w-11 h-11 bg-slate-100 rounded-2xl flex items-center justify-center">
                <Pen size={20} className="text-slate-500" />
              </div>
              <div className="text-left flex-1">
                <p className="text-[15px] font-bold text-slate-900">{t('contract_custom', language)}</p>
                <p className="text-[11px] text-slate-400 mt-0.5">{t('contract_custom_desc', language)}</p>
              </div>
              <ArrowRight size={18} className="text-slate-300" />
            </motion.button>

            {/* Upload template */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.4 }}
            >
              <div
                onClick={() => fileInputRef.current?.click()}
                className={`w-full p-4 rounded-[24px] border-2 border-dashed flex items-center gap-4 cursor-pointer transition-colors ${templateFileBase64 ? 'border-green-400 bg-green-50' : 'border-slate-200 hover:border-blue-400 bg-white/50'}`}
              >
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.txt" onChange={handleFileUpload} />

                {templateFileBase64 ? (
                  <>
                    <div className="w-11 h-11 bg-green-100 rounded-2xl flex items-center justify-center">
                      <Check size={20} className="text-green-600" />
                    </div>
                    <div className="text-left flex-1">
                      <p className="text-[15px] font-bold text-green-700">Uploaded</p>
                      <p className="text-[11px] text-green-600 mt-0.5">{templateType === 'image' ? 'Image' : 'Text'}</p>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="w-11 h-11 bg-slate-50 rounded-2xl flex items-center justify-center">
                      <Upload size={20} className="text-slate-400" />
                    </div>
                    <div className="text-left flex-1">
                      <p className="text-[15px] font-bold text-slate-500">{t('contract_upload', language)}</p>
                      <p className="text-[11px] text-slate-400 mt-0.5">{t('contract_upload_desc', language)}</p>
                    </div>
                  </>
                )}
              </div>

              {/* Adaptation prompt (shown when file uploaded) */}
              {templateFileBase64 && (
                <div className="mt-3 space-y-3">
                  <div className="glass-card p-4 rounded-[24px] bg-white border border-slate-100">
                    <textarea
                      value={adaptationPrompt}
                      onChange={(e) => setAdaptationPrompt(e.target.value)}
                      onFocus={handleInputFocus}
                      placeholder={t('contract_placeholder_adapt', language)}
                      className="w-full h-28 bg-slate-50 rounded-[16px] p-4 text-sm font-medium text-slate-900 focus:outline-none resize-none"
                    />
                  </div>
                  <button
                    onClick={handleGenerateFromTemplate}
                    disabled={!adaptationPrompt.trim()}
                    className={`w-full py-5 rounded-[26px] shadow-xl flex items-center justify-center gap-2 text-[17px] font-bold transition-all border border-white/50 ${!adaptationPrompt.trim() ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white'}`}
                  >
                    <span>{t('contract_btn_fill', language)}</span>
                    <FileText size={20} className="opacity-60" />
                  </button>
                </div>
              )}
            </motion.div>

            {/* History */}
            {history.length > 0 && (
              <div className="mt-8">
                <div className="flex items-center gap-2 mb-4 px-1">
                  <HistoryIcon size={16} className="text-slate-400" />
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">History</h3>
                </div>
                <div className="space-y-3">
                  {history.map((item) => (
                    <div
                      key={item.id}
                      onClick={() => handleRestore(item)}
                      className="bg-white p-4 rounded-[20px] border border-slate-100 shadow-sm flex items-start gap-3 active:scale-[0.98] transition-all cursor-pointer group"
                    >
                      <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center text-slate-400 group-hover:bg-slate-900 group-hover:text-white transition-colors shrink-0">
                        <FileText size={18} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-bold text-slate-900 line-clamp-2 leading-tight mb-1">
                          {item.prompt || "Untitled"}
                        </p>
                        <div className="flex items-center gap-2 text-[10px] text-slate-400">
                          <Clock size={10} />
                          <span>{item.createdAt ? new Date(item.createdAt).toLocaleDateString() : 'Recent'}</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* =========== STEP: CUSTOM (free text) =========== */}
        {step === 'custom' && (
          <div className="space-y-5 animate-slide-up">
            <div className="glass-card p-1 rounded-[32px] shadow-2xl shadow-blue-900/5 border border-slate-100 relative bg-white/60">
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                onFocus={handleInputFocus}
                placeholder={t('contract_placeholder_create', language)}
                className="w-full h-48 bg-transparent rounded-[30px] pt-6 pb-4 px-5 text-[17px] font-medium text-slate-900 placeholder-slate-400 focus:outline-none resize-none leading-relaxed"
                autoFocus
              />
            </div>

            <button
              onClick={() => handleGenerateFromText()}
              disabled={!description.trim()}
              className={`w-full py-5 rounded-[26px] shadow-xl flex items-center justify-center gap-2 text-[17px] font-bold transition-all border border-white/50 ${!description.trim() ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white shadow-purple-900/20'}`}
            >
              <span>{t('contract_btn_create', language)}</span>
              <FileText size={20} className="opacity-60" />
            </button>
          </div>
        )}

        {/* =========== STEP 2: QUESTIONS =========== */}
        {step === 'questions' && (
          <div className="space-y-5 animate-slide-up">

            {/* Selected type badge */}
            <div className="flex items-center gap-2 px-1">
              <div className={`w-8 h-8 ${CONTRACT_TYPES.find(ct => ct.id === selectedType)?.bg || 'bg-slate-100'} rounded-xl flex items-center justify-center`}>
                {(() => {
                  const ct = CONTRACT_TYPES.find(c => c.id === selectedType);
                  if (ct) {
                    const Icon = ct.icon;
                    return <Icon size={16} className={ct.color} />;
                  }
                  return null;
                })()}
              </div>
              <p className="text-[15px] font-bold text-slate-900">{t(`contract_type_${selectedType}`, language)}</p>
            </div>

            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">
              {t('contract_ai_questions', language)}
            </p>

            {loadingQuestions ? (
              <div className="flex flex-col items-center justify-center py-16">
                <LoadingSpinner />
                <p className="text-sm text-slate-400 mt-4 animate-pulse">{t('contract_ai_questions', language)}</p>
              </div>
            ) : (
              <>
                <div className="space-y-4">
                  {questions.map((q, idx) => (
                    <motion.div
                      key={idx}
                      initial={{ opacity: 0, y: 15 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.08 * idx }}
                      className="glass-card p-4 rounded-[24px] bg-white border border-slate-100"
                    >
                      <label className="text-[12px] font-bold text-slate-600 mb-2 block leading-snug">
                        {q.question}
                        {q.required && <span className="text-rose-400 ml-1">*</span>}
                      </label>
                      <input
                        type="text"
                        value={answers[idx] || ''}
                        onChange={(e) => setAnswers(prev => ({ ...prev, [idx]: e.target.value }))}
                        onFocus={handleInputFocus}
                        placeholder={q.placeholder}
                        className="w-full bg-slate-50 rounded-[16px] px-4 py-3 text-[15px] font-medium text-slate-900 placeholder-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-200 transition-all"
                      />
                    </motion.div>
                  ))}
                </div>

                <button
                  onClick={handleGenerateFromAnswers}
                  disabled={!hasRequiredAnswers}
                  className={`w-full py-5 rounded-[26px] shadow-xl flex items-center justify-center gap-2 text-[17px] font-bold transition-all border border-white/50 mt-2 ${!hasRequiredAnswers ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white shadow-purple-900/20'}`}
                >
                  <span>{t('contract_btn_create', language)}</span>
                  <FileText size={20} className="opacity-60" />
                </button>
              </>
            )}
          </div>
        )}

        {/* =========== STEP 3: GENERATING =========== */}
        {step === 'generating' && (
          <div className="h-[60vh] flex flex-col items-center justify-center text-center">
            <div className="relative mb-6">
              <div className="absolute inset-0 bg-emerald-500 blur-2xl opacity-20 animate-pulse rounded-full"></div>
              <div className="w-20 h-20 bg-white rounded-[28px] flex items-center justify-center shadow-xl border border-slate-100 relative z-10">
                <LoadingSpinner />
              </div>
            </div>
            <h3 className="text-xl font-bold text-slate-900 mb-2">
              {isEditing ? t('contract_editing', language) : t('contract_generating', language)}
            </h3>
            <p className="text-sm text-slate-500 max-w-[240px] animate-pulse">
              {t('contract_generating_desc', language)}
            </p>
          </div>
        )}

        {/* =========== STEP 4: RESULT =========== */}
        {step === 'result' && (
          <div className="animate-fade-in flex flex-col h-full items-center">

            {/* Success badge */}
            <div className="flex items-center gap-2 mb-4 self-start">
              <div className="w-6 h-6 bg-emerald-100 rounded-full flex items-center justify-center">
                <Check size={14} className="text-emerald-600" />
              </div>
              <p className="text-sm font-bold text-emerald-700">{t('contract_ready', language)}</p>
            </div>

            {/* Document preview */}
            <div className="w-full relative mb-6">
              <div className="bg-white text-slate-900 p-[15mm] rounded-[2px] shadow-2xl shadow-slate-400/20 border border-slate-200 min-h-[400px] relative overflow-hidden font-serif">
                <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'radial-gradient(circle, #000 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>
                <div className="prose prose-sm max-w-none prose-headings:font-serif prose-headings:uppercase prose-headings:tracking-widest prose-p:leading-relaxed prose-p:text-justify prose-li:my-1 text-[13px] sm:text-[15px]">
                  <ReactMarkdown>{result}</ReactMarkdown>
                </div>
              </div>
            </div>

            {/* Edit section */}
            <div className="w-full mb-4">
              <div className="glass-card p-1 rounded-[24px] bg-white border border-slate-100 flex items-center gap-2">
                <input
                  type="text"
                  value={editText}
                  onChange={(e) => setEditText(e.target.value)}
                  onFocus={handleInputFocus}
                  onKeyDown={(e) => { if (e.key === 'Enter' && editText.trim()) handleEdit(); }}
                  placeholder={t('contract_edit_placeholder', language)}
                  className="flex-1 bg-transparent px-4 py-3.5 text-[15px] font-medium text-slate-900 placeholder-slate-300 focus:outline-none"
                  disabled={isEditing}
                />
                <button
                  onClick={handleEdit}
                  disabled={!editText.trim() || isEditing}
                  className={`w-12 h-12 rounded-[20px] flex items-center justify-center shrink-0 transition-all ${!editText.trim() || isEditing ? 'bg-slate-100 text-slate-300' : 'bg-slate-900 text-white'}`}
                >
                  {isEditing ? <LoadingSpinner /> : <Send size={18} />}
                </button>
              </div>
            </div>

            {/* Action buttons */}
            <div className="w-full space-y-3">
              <div className="flex gap-3">
                <button
                  onClick={handleDownloadWord}
                  className="flex-1 bg-slate-900 text-white font-bold py-4 rounded-[24px] flex items-center justify-center gap-2 shadow-xl active:scale-95 transition-transform"
                >
                  <FileType size={20} />
                  <span>DOCX</span>
                </button>
                <button
                  onClick={() => { if(navigator.share) navigator.share({ title: 'Contract', text: result }) }}
                  className="w-16 bg-white text-slate-900 border border-slate-200 font-bold py-4 rounded-[24px] flex items-center justify-center shadow-lg active:scale-95 transition-transform"
                >
                  <Share2 size={20} />
                </button>
              </div>

              <div className="flex gap-3">
                <button
                  onClick={() => { navigator.clipboard.writeText(result); setCopied(true); setTimeout(() => setCopied(false), 2000); }}
                  className="flex-1 bg-white text-slate-600 font-bold py-3 rounded-[20px] flex items-center justify-center gap-2 shadow-sm border border-slate-100 active:scale-95 transition-transform text-sm"
                >
                  {copied ? <Check size={16} className="text-green-500"/> : <Copy size={16} />}
                  <span>{copied ? t('btn_copied', language) : t('btn_copy', language)}</span>
                </button>

                <button
                  onClick={handleReset}
                  className="bg-white text-slate-600 font-bold py-3 px-5 rounded-[20px] flex items-center justify-center gap-2 shadow-sm border border-slate-100 active:scale-95 transition-transform text-sm"
                >
                  <RefreshCw size={16} />
                  <span className="hidden sm:inline">{t('contract_btn_new', language)}</span>
                </button>
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

