  32→const normalizeUrl = (value: string) => value.replace(/\/$/, '');
  33→const PROD_WEB_URL = normalizeUrl(process.env.EXPO_PUBLIC_WEB_URL || 'https://x5marketing.com');
  34→const DEV_WEB_URL = normalizeUrl(process.env.EXPO_PUBLIC_WEB_URL_DEV || PROD_WEB_URL);
  35→const INITIAL_WEB_URL = __DEV__ ? DEV_WEB_URL : PROD_WEB_URL;
  36→
  37→const ALLOWED_MESSAGE_TYPES = new Set([
  38→  'WEB_READY',
  39→  'LOGIN_APPLE',
  40→  'LOGIN_GOOGLE',
  41→  'LOGIN_EMAIL',
  42→  'PAYMENT_REQUEST',
  43→]);
  44→const ALLOWED_PRODUCT_IDS = new Set(['x5_pro_monthly', 'x5_pro_yearly', 'x5_credits_1000']);
  45→const PURCHASE_TX_CACHE_KEY_PREFIX = 'x5_rc_tx_cache_v1:';
  46→const MAX_TRACKED_TRANSACTIONS = 150;
  47→
  48→type NativeAuthProvider = 'apple' | 'google' | 'email';
  49→
  50→type NativeAuthResult = {
  51→  success: boolean;
  52→  provider?: NativeAuthProvider;
  53→  accessToken?: string;
  54→  refreshToken?: string;
  55→  error?: string;
  56→  canceled?: boolean;
  57→  confirmationRequired?: boolean;
  58→};
  59→
  60→type BridgeIncomingMessage =
  61→  | { type: 'WEB_READY' }
  62→  | { type: 'LOGIN_APPLE' }
  63→  | { type: 'LOGIN_GOOGLE' }
  64→  | { type: 'LOGIN_EMAIL'; payload: { email: string; password: string; isSignUp?: boolean } }
  65→  | { type: 'PAYMENT_REQUEST'; payload: { productId: string } };
  66→
  67→const isRecord = (value: unknown): value is Record<string, unknown> =>
  68→  typeof value === 'object' && value !== null;
  69→
  70→const parseIncomingMessage = (raw: string): BridgeIncomingMessage | null => {
  71→  if (!raw || raw.length > 10_000) return null;
  72→
  73→  let parsed: unknown;
  74→  try {
  75→    parsed = JSON.parse(raw);
  76→  } catch {
  77→    return null;
  78→  }
  79→
  80→  if (!isRecord(parsed)) return null;
  81→  const type = parsed.type;
  82→  if (typeof type !== 'string' || !ALLOWED_MESSAGE_TYPES.has(type)) return null;
  83→
  84→  if (type === 'WEB_READY' || type === 'LOGIN_APPLE' || type === 'LOGIN_GOOGLE') {
  85→    return { type };
  86→  }
  87→
  88→  if (type === 'LOGIN_EMAIL') {
  89→    if (!isRecord(parsed.payload)) return null;
  90→    const email = parsed.payload.email;
  91→    const password = parsed.payload.password;
  92→    const isSignUp = parsed.payload.isSignUp;
  93→
  94→    if (typeof email !== 'string' || !email.includes('@') || email.length > 320) return null;
  95→    if (typeof password !== 'string' || password.length < 6 || password.length > 200) return null;
  96→    if (isSignUp !== undefined && typeof isSignUp !== 'boolean') return null;
  97→
  98→    return { type, payload: { email, password, isSignUp } };
  99→  }
 100→
 101→  if (!isRecord(parsed.payload)) return null;
 102→  const productId = parsed.payload.productId;
 103→  if (typeof productId !== 'string' || productId.length < 3 || productId.length > 64) return null;
 104→  if (!ALLOWED_PRODUCT_IDS.has(productId)) return null;
 105→
 106→  return { type: 'PAYMENT_REQUEST', payload: { productId } };
 107→};
