 137→const markTransactionIfNew = async (userId: string, transactionId: string): Promise<boolean> => {
 138→  const key = `${PURCHASE_TX_CACHE_KEY_PREFIX}${userId}`;
 139→
 140→  try {
 141→    const raw = await AsyncStorage.getItem(key);
 142→    const parsed = raw ? JSON.parse(raw) : [];
 143→    const txList: string[] = Array.isArray(parsed)
 144→      ? parsed.filter((value): value is string => typeof value === 'string')
 145→      : [];
 146→
 147→    if (txList.includes(transactionId)) return false;
 148→
 149→    const next = [transactionId, ...txList].slice(0, MAX_TRACKED_TRANSACTIONS);
 150→    await AsyncStorage.setItem(key, JSON.stringify(next));
 151→    return true;
 152→  } catch (error) {
 153→    // Fail-open: allow purchase rather than block user. Server-side idempotency is the real safeguard.
 154→    console.error('[Payment] Transaction dedup cache error:', transactionId, error);
 155→    return true;
 156→  }
 157→};
