 175→function AnimatedSplash() {
 176→  const logoScale = useRef(new Animated.Value(0.3)).current;
 177→  const logoOpacity = useRef(new Animated.Value(0)).current;
 178→  const titleOpacity = useRef(new Animated.Value(0)).current;
 179→  const titleTranslateY = useRef(new Animated.Value(20)).current;
