 182→  const dot1 = useRef(new Animated.Value(0)).current;
 183→  const dot2 = useRef(new Animated.Value(0)).current;
 184→  const dot3 = useRef(new Animated.Value(0)).current;
 185→
 186→  useEffect(() => {
 187→    // Logo: fade in + spring scale
 188→    Animated.parallel([
 189→      Animated.timing(logoOpacity, {
 190→        toValue: 1,
 191→        duration: 600,
 192→        useNativeDriver: true,
 193→      }),
 194→      Animated.spring(logoScale, {
 195→        toValue: 1,
 196→        tension: 50,
 197→        friction: 7,
 198→        useNativeDriver: true,
 199→      }),
 200→    ]).start();
 201→
 202→    // Pulsing ring around logo
 203→    Animated.sequence([
 204→      Animated.delay(400),
 205→      Animated.parallel([
 206→        Animated.timing(ringOpacity, { toValue: 0.3, duration: 500, useNativeDriver: true }),
 207→        Animated.timing(ringScale, { toValue: 1, duration: 500, useNativeDriver: true }),
 208→      ]),
 209→    ]).start(() => {
 210→      // Continuous pulse
 211→      Animated.loop(
 212→        Animated.sequence([
 213→          Animated.parallel([
 214→            Animated.timing(ringScale, { toValue: 1.15, duration: 1200, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
 215→            Animated.timing(ringOpacity, { toValue: 0.1, duration: 1200, useNativeDriver: true }),
 216→          ]),
 217→          Animated.parallel([
 218→            Animated.timing(ringScale, { toValue: 1, duration: 1200, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
 219→            Animated.timing(ringOpacity, { toValue: 0.3, duration: 1200, useNativeDriver: true }),
 220→          ]),
 221→        ]),
 222→      ).start();
 223→    });
 224→
 225→    // Title: slide up + fade in
 226→    Animated.sequence([
 227→      Animated.delay(500),
 228→      Animated.parallel([
 229→        Animated.timing(titleOpacity, { toValue: 1, duration: 500, useNativeDriver: true }),
 230→        Animated.timing(titleTranslateY, { toValue: 0, duration: 500, easing: Easing.out(Easing.cubic), useNativeDriver: true }),
 231→      ]),
 232→    ]).start();
 233→
 234→    // Loading dots: staggered bounce
 235→    const animateDot = (dot: Animated.Value, delay: number) =>
 236→      Animated.loop(
 237→        Animated.sequence([
 238→          Animated.delay(delay),
 239→          Animated.timing(dot, { toValue: -8, duration: 300, easing: Easing.out(Easing.quad), useNativeDriver: true }),
 240→          Animated.timing(dot, { toValue: 0, duration: 300, easing: Easing.in(Easing.quad), useNativeDriver: true }),
 241→          Animated.delay(600 - delay),
 242→        ]),
 243→      );
 244→    Animated.sequence([
 245→      Animated.delay(800),
 246→      Animated.parallel([
 247→        animateDot(dot1, 0),
 248→        animateDot(dot2, 150),
 249→        animateDot(dot3, 300),
 250→      ]),
 251→    ]).start();
 252→  }, [logoScale, logoOpacity, titleOpacity, titleTranslateY, ringScale, ringOpacity, dot1, dot2, dot3]);
 253→
 254→  return (
 255→    <View style={styles.splashOverlay}>
 256→      {/* Pulsing ring */}
 257→      <Animated.View
 258→        style={[
 259→          styles.splashRing,
 260→          { transform: [{ scale: ringScale }], opacity: ringOpacity },
 261→        ]}
 262→      />
 263→
 264→      {/* Logo with spring animation */}
 265→      <Animated.View
 266→        style={{
 267→          transform: [{ scale: logoScale }],
 268→          opacity: logoOpacity,
 269→        }}
 270→      >
 271→        <Image
 272→          source={require('../../assets/icon.png')}
 273→          style={styles.splashIcon}
 274→          resizeMode="contain"
 275→        />
 276→      </Animated.View>
 277→
 278→      {/* Title slides up */}
 279→      <Animated.Text
 280→        style={[
 281→          styles.splashTitle,
 282→          { opacity: titleOpacity, transform: [{ translateY: titleTranslateY }] },
 283→        ]}
 284→      >
 285→        X5 Marketing
 286→      </Animated.Text>
 287→
 288→      {/* Bouncing dots */}
 289→      <View style={styles.dotsRow}>
 290→        {[dot1, dot2, dot3].map((dot, i) => (
 291→          <Animated.View
 292→            key={i}
 293→            style={[styles.dot, { transform: [{ translateY: dot }] }]}
 294→          />
 295→        ))}
 296→      </View>
 297→    </View>
 298→  );
 299→}
