 601→  const handleAppleSignIn = async () => {
 602→    const available = await AppleAuthentication.isAvailableAsync();
 603→    if (!available) {
 604→      dispatchAuthResult({ success: false, error: 'Apple Sign-In not available', provider: 'apple' });
 605→      return;
 606→    }
 607→
 608→    try {
 609→      const randomBytes = await Crypto.getRandomBytesAsync(32);
 610→      const rawNonce = Array.from(randomBytes, (b) => b.toString(16).padStart(2, '0')).join('');
 611→      const hashedNonce = await Crypto.digestStringAsync(
 612→        Crypto.CryptoDigestAlgorithm.SHA256,
 613→        rawNonce,
 614→      );
 615→
 616→      const credential = await AppleAuthentication.signInAsync({
 617→        requestedScopes: [
 618→          AppleAuthentication.AppleAuthenticationScope.FULL_NAME,
 619→          AppleAuthentication.AppleAuthenticationScope.EMAIL,
 620→        ],
 621→        nonce: hashedNonce,
 622→      });
 623→
 624→      if (!credential.identityToken) {
 625→        dispatchAuthResult({ success: false, error: 'No identity token', provider: 'apple' });
 626→        return;
 627→      }
 628→
 629→      const { data, error } = await supabase.auth.signInWithIdToken({
 630→        provider: 'apple',
 631→        token: credential.identityToken,
 632→        nonce: rawNonce,
 633→      });
 634→
 635→      if (error) {
 636→        dispatchAuthResult({ success: false, error: error.message, provider: 'apple' });
 637→        return;
 638→      }
 639→
 640→      const sessionFromAuth = data.session || (await supabase.auth.getSession()).data.session;
 641→      if (!sessionFromAuth) {
 642→        dispatchAuthResult({ success: false, error: 'Apple sign-in session not found', provider: 'apple' });
 643→        return;
 644→      }
 645→
 646→      await ensureProfile(sessionFromAuth);
 647→      dispatchAuthBootstrap(sessionFromAuth);
 648→      dispatchAuthResult({
 649→        success: true,
 650→        accessToken: sessionFromAuth.access_token,
 651→        refreshToken: sessionFromAuth.refresh_token,
 652→        provider: 'apple',
 653→      });
 654→    } catch (e: unknown) {
 655→      const code = (e as { code?: string })?.code;
 656→      if (code === 'ERR_REQUEST_CANCELED') {
 657→        dispatchAuthResult({ success: false, canceled: true, provider: 'apple' });
 658→        return;
 659→      }
 660→
 661→      console.error('[Apple Sign-In] Failed:', (e as Error)?.message || code, e);
 662→
 663→      const fallback = (await supabase.auth.getSession()).data.session;
 664→      if (fallback) {
 665→        console.warn('[Apple Sign-In] Using pre-existing session as fallback');
 666→        dispatchAuthBootstrap(fallback);
 667→        dispatchAuthResult({
 668→          success: true,
 669→          accessToken: fallback.access_token,
 670→          refreshToken: fallback.refresh_token,
 671→        });
 672→        return;
 673→      }
 674→
 675→      dispatchAuthResult({ success: false, error: (e as Error)?.message || code || 'UNKNOWN', provider: 'apple' });
 676→    }
 677→  };
