 758→  const handlePayment = async (payload: { productId: string }) => {
 759→    const requestedProductId = payload.productId;
 760→    if (paymentInFlightRef.current) {
 761→      dispatchPaymentResult({
 762→        success: false,
 763→        error: 'Payment is already in progress',
