 768→
 769→    paymentInFlightRef.current = true;
 770→    try {
 771→      const finalizePurchase = async (params: {
 772→        purchasedProductId: string;
 773→        transactionId?: string;
 774→        customerInfo: { entitlements: { active: Record<string, unknown> } };
 775→      }) => {
 776→        const { purchasedProductId, transactionId, customerInfo } = params;
 777→
 778→        if (requestedProductId && purchasedProductId !== requestedProductId) {
 779→          dispatchPaymentResult({
 780→            success: false,
 781→            error: `Purchased product mismatch: expected ${requestedProductId}, got ${purchasedProductId}`,
 782→            productId: requestedProductId,
