 790→          dispatchPaymentResult({
 791→            success: false,
 792→            error: 'Missing transaction ID for credits purchase',
 793→            productId: requestedProductId || purchasedProductId,
 794→            purchasedProductId,
 795→          });
 796→          return;
 797→        }
 798→
 799→        if (transactionId) {
 800→          const userId = session?.user?.id || 'anon';
 801→          const isNewTransaction = await markTransactionIfNew(userId, transactionId);
 802→          if (!isNewTransaction) {
 803→            dispatchPaymentResult({
 804→              success: false,
 805→              error: 'This purchase was already processed',
 806→              alreadyProcessed: true,
 807→              productId: requestedProductId || purchasedProductId,
 808→              purchasedProductId,
 809→              transactionId,
 810→            });
 811→            return;
 812→          }
 813→        }
 814→
 815→        const isActive = customerInfo.entitlements.active.pro !== undefined;
 816→        dispatchPaymentResult({
 817→          success: true,
 818→          productId: requestedProductId || purchasedProductId,
 819→          purchasedProductId,
 820→          transactionId,
 821→          isActive,
 822→        });
 823→      };
 824→
 825→      const offerings = await Purchases.getOfferings();
 826→      let pkg = offerings.current?.availablePackages[0];
 827→
 828→      if (requestedProductId && offerings.current) {
 829→        const matched = offerings.current.availablePackages.find(
 830→          (candidate) => candidate.product.identifier === requestedProductId,
 831→        );
 832→        if (matched) pkg = matched;
 833→      }
 834→
 835→      if (pkg) {
 836→        const purchase = await Purchases.purchasePackage(pkg);
 837→        await finalizePurchase({
 838→          purchasedProductId: purchase.productIdentifier || pkg.product.identifier,
 839→          transactionId: purchase.transaction?.transactionIdentifier,
 840→          customerInfo: purchase.customerInfo,
 841→        });
 842→        return;
 843→      }
 844→
 845→      // Fallback path: purchase by product ID when offerings are temporarily empty/misconfigured.
 846→      const productIds = requestedProductId ? [requestedProductId] : Array.from(ALLOWED_PRODUCT_IDS);
 847→      const products = await Purchases.getProducts(productIds);
 848→      const product = requestedProductId
 849→        ? products.find((candidate) => candidate.identifier === requestedProductId)
 850→        : products[0];
 851→
 852→      if (!product) {
 853→        dispatchPaymentResult({
 854→          success: false,
 855→          error: 'No products available in RevenueCat',
 856→          productId: requestedProductId,
 857→        });
 858→        return;
 859→      }
 860→
 861→      const purchase = await Purchases.purchaseStoreProduct(product);
 862→      await finalizePurchase({
 863→        purchasedProductId: purchase.productIdentifier || product.identifier,
 864→        transactionId: purchase.transaction?.transactionIdentifier,
 865→        customerInfo: purchase.customerInfo,
 866→      });
 867→    } catch (e) {
 868→      const err = e as { message?: string; userCancelled?: boolean };
 869→      const canceled = !!err.userCancelled;
 870→      const normalizedMessage =
 871→        !canceled && err.message?.toLowerCase().includes('offerings')
 872→          ? 'RevenueCat offerings are not configured'
 873→          : err.message || 'Payment failed';
 874→      dispatchPaymentResult({
 875→        success: false,
 876→        canceled,
 877→        error: canceled ? undefined : normalizedMessage,
 878→        productId: requestedProductId,
 879→      });
 880→    } finally {
