 45→    // Nickname editing state
 46→    const [isEditingName, setIsEditingName] = useState(false);
 47→    const [newName, setNewName] = useState(user.name);
 48→    const [isEditingNickname, setIsEditingNickname] = useState(false);
 49→    const [newNickname, setNewNickname] = useState(user.nickname || '');
 50→    const [nicknameError, setNicknameError] = useState('');
 51→    const [isEditingBio, setIsEditingBio] = useState(false);
 52→    const [newBio, setNewBio] = useState(user.bio || '');
 53→    const [isEditingServices, setIsEditingServices] = useState(false);
 54→    const [newService, setNewService] = useState('');
 55→    const [services, setServices] = useState<string[]>(user.services || []);
 56→
 57→    const handleSaveName = async () => {
 58→        if (!newName.trim() || newName === user.name) {
 59→            setIsEditingName(false);
 60→            setNewName(user.name);
 61→            return;
 62→        }
 63→
 64→        const updatedUser = { ...user, name: newName.trim() };
 65→
 66→        // Update parent state
 67→        if (onUpdateUser) onUpdateUser(updatedUser);
 68→
 69→        // Save to localStorage
 70→        localStorage.setItem('x5_user', JSON.stringify(updatedUser));
 71→
 72→        // Save to Supabase
 73→        if (user.id && !user.isGuest) {
 74→            try {
 75→                await supabase.from('profiles').update({ name: newName.trim() }).eq('id', user.id);
 76→            } catch (e) {
 77→                console.error("Failed to save name to Supabase", e);
 78→            }
 79→        }
 80→
 81→        setIsEditingName(false);
 82→    };
 83→
 84→    const handleSaveNickname = async () => {
 85→        const nick = newNickname.trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
 86→        if (!nick || nick.length < 3) {
 87→            setNicknameError('Минимум 3 символа (a-z, 0-9, _)');
 88→            return;
 89→        }
 90→        if (nick === user.nickname) {
 91→            setIsEditingNickname(false);
 92→            return;
 93→        }
 94→
 95→        // Check uniqueness
 96→        if (user.id && !user.isGuest) {
 97→            try {
 98→                const { data: existing } = await supabase
 99→                    .from('profiles')
100→                    .select('id')
101→                    .eq('nickname', nick);
102→                if (existing && existing.length > 0 && existing[0].id !== user.id) {
103→                    setNicknameError('Этот никнейм уже занят');
104→                    return;
105→                }
106→
107→                await supabase.from('profiles').update({ nickname: nick }).eq('id', user.id);
108→                const updatedUser = { ...user, nickname: nick };
109→                if (onUpdateUser) onUpdateUser(updatedUser);
110→                localStorage.setItem('x5_user', JSON.stringify(updatedUser));
111→                setNicknameError('');
112→            } catch (e) {
113→                console.error("Failed to save nickname", e);
114→            }
115→        }
116→
117→        setIsEditingNickname(false);
118→    };
