 94→const isRecord = (value: unknown): value is Record<string, unknown> =>
 95→    typeof value === 'object' && value !== null;
 96→
 97→const parseEventDetail = (rawDetail: unknown): unknown => {
 98→    if (typeof rawDetail !== 'string') return rawDetail;
 99→    try {
100→        return JSON.parse(rawDetail);
101→    } catch {
102→        return null;
103→    }
104→};
105→
106→const parseNativeAuthResult = (rawDetail: unknown): NativeAuthResultPayload | null => {
107→    const detail = parseEventDetail(rawDetail);
108→    if (!isRecord(detail)) return null;
109→    if (typeof detail.success !== 'boolean') return null;
110→
111→    if (
112→        detail.provider !== undefined &&
113→        detail.provider !== 'apple' &&
114→        detail.provider !== 'google' &&
115→        detail.provider !== 'email'
116→    ) {
117→        return null;
118→    }
119→
120→    if (detail.accessToken !== undefined && typeof detail.accessToken !== 'string') return null;
121→    if (detail.refreshToken !== undefined && typeof detail.refreshToken !== 'string') return null;
122→    if (detail.error !== undefined && typeof detail.error !== 'string') return null;
123→    if (detail.canceled !== undefined && typeof detail.canceled !== 'boolean') return null;
124→    if (detail.cancelled !== undefined && typeof detail.cancelled !== 'boolean') return null;
125→
126→    return detail as NativeAuthResultPayload;
127→};
128→
129→const parseNativeAuthBootstrap = (rawDetail: unknown): NativeAuthBootstrapPayload | null => {
130→    const detail = parseEventDetail(rawDetail);
131→    if (!isRecord(detail)) return null;
132→    if (typeof detail.id !== 'string' || !detail.id) return null;
133→    if (detail.name !== undefined && typeof detail.name !== 'string') return null;
134→    if (detail.email !== undefined && typeof detail.email !== 'string') return null;
135→    if (detail.avatar !== undefined && typeof detail.avatar !== 'string') return null;
136→    if (detail.isGuest !== undefined && typeof detail.isGuest !== 'boolean') return null;
137→    if (detail.credits !== undefined && typeof detail.credits !== 'number') return null;
138→    if (detail.purchasedCourseIds !== undefined && !Array.isArray(detail.purchasedCourseIds)) return null;
139→    return detail as NativeAuthBootstrapPayload;
140→};
