            {/* DELETE ACCOUNT CONFIRMATION */}
            {showDeleteConfirm && (
                <div className="fixed inset-0 z-[60] bg-black/40 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
                    <div className="bg-white rounded-[32px] w-full max-w-sm shadow-2xl relative overflow-hidden animate-scale-in p-6">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold text-red-600">
                                {language === 'ru' ? 'Удалить аккаунт?' : language === 'kz' ? 'Аккаунтты жою?' : 'Delete Account?'}
                            </h3>
                            <button onClick={() => setShowDeleteConfirm(false)} className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 hover:bg-slate-200 transition-colors">
                                <X size={18} />
                            </button>
                        </div>
                        <p className="text-sm text-slate-600 mb-6 leading-relaxed">
                            {language === 'ru'
                                ? 'Все ваши данные, история генераций и подписки будут удалены безвозвратно. Это действие нельзя отменить.'
                                : language === 'kz'
                                    ? 'Барлық деректеріңіз, генерация тарихы және жазылымдар біржола жойылады. Бұл әрекетті кері қайтару мүмкін емес.'
                                    : 'All your data, generation history, and subscriptions will be permanently deleted. This action cannot be undone.'}
                        </p>
                        <div className="space-y-3">
                            <button
                                onClick={async () => {
                                    setIsDeleting(true);
                                    try {
                                        if (onDeleteAccount) await onDeleteAccount();
                                    } finally {
                                        setIsDeleting(false);
                                        setShowDeleteConfirm(false);
                                    }
                                }}
                                disabled={isDeleting}
                                className="w-full py-4 bg-red-600 text-white font-bold rounded-[20px] flex items-center justify-center gap-2 active:scale-95 transition-all"
                            >
                                {isDeleting
                                    ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                    : <><UserX size={18} /><span>{language === 'ru' ? 'Да, удалить' : language === 'kz' ? 'Иә, жою' : 'Yes, Delete'}</span></>
                                }
                            </button>
                            <button
                                onClick={() => setShowDeleteConfirm(false)}
                                className="w-full py-4 bg-slate-100 text-slate-700 font-bold rounded-[20px] active:scale-95 transition-all"
                            >
                                {language === 'ru' ? 'Отмена' : language === 'kz' ? 'Бас тарту' : 'Cancel'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Header */}
            <div className="px-6 pt-16 pb-6 shrink-0">
                <div className="flex items-center justify-between mb-2 relative">
                    <button onClick={onClose} className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-md active:scale-95 transition-transform border border-slate-100">
                        <ChevronLeft size={22} strokeWidth={2.5} className="text-slate-700" />
                    </button>
                    <div className="w-12 h-12 bg-gradient-to-br from-slate-700 to-slate-900 rounded-2xl flex items-center justify-center shadow-lg">
                        <Settings size={24} className="text-white" />
                    </div>
                    <div onClick={onDevTap} className="w-10 h-10 opacity-0 active:opacity-10 bg-red-500/20 z-50 cursor-pointer"></div>
                </div>
                <h2 className="text-3xl font-black text-slate-900 mt-4 mb-1">{t('settings_title', language)}</h2>
                <p className="text-sm text-slate-500 font-medium">{language === 'ru' ? 'Управление приложением' : 'Manage your app'}</p>
            </div>

            <div className="space-y-6 overflow-y-auto pb-10 no-scrollbar px-6 flex-1">

                {/* Account */}
                <div>
                    <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest ml-4 mb-3">{t('settings_account', language)}</h3>
                    <GlassButton title={t('settings_language', language)} subtitle={getLanguageLabel(language)} icon={Globe} onClick={() => onNavigateTo('languages')} colorClass="text-blue-500" />
                </div>

                {/* Info */}
                <div>
                    <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest ml-4 mb-3">{t('settings_info', language)}</h3>
                    <GlassButton title={t('settings_support', language)} icon={Info} onClick={() => onNavigateTo('contacts')} colorClass="text-purple-600" />
                    <GlassButton title={t('settings_offer', language)} icon={ScrollText} onClick={() => onNavigateTo('offer')} colorClass="text-emerald-600" />
                    <GlassButton title={t('settings_privacy', language)} icon={Shield} onClick={() => onNavigateTo('privacy')} colorClass="text-slate-500" />
                    <GlassButton title={t('settings_payment', language)} icon={CreditCard} onClick={() => onNavigateTo('payment')} colorClass="text-orange-500" />
                </div>

                {/* System */}
                <div>
                    <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest ml-4 mb-3">{t('settings_system', language)}</h3>

                    {/* Platform Switcher (Only Visible in Dev Mode) */}
                    {isDevMode && (
                        <GlassButton
                            title={t('settings_platform', language)}
                            subtitle={getPlatformLabel()}
                            icon={getPlatformIcon()}
                            onClick={() => setShowPlatformSelect(true)}
                            colorClass={getPlatformColor()}
                        />
                    )}

                    {/* Biometric Toggle - HIDDEN ON WEB */}
                    {!isWeb && (
                        <GlassButton
                            title={isAndroid ? t('settings_touchid', language) : t('settings_faceid', language)}
                            subtitle={faceIdEnabled ? (language === 'en' ? "Enabled" : "Активно") : (language === 'en' ? "Disabled" : "Отключено")}
                            icon={isAndroid ? Fingerprint : ScanFace}
                            onClick={toggleFaceId}
                            colorClass={faceIdEnabled ? "text-green-500" : "text-slate-400"}
                        />
                    )}

                    <GlassButton
                        title={t('settings_ram', language)}
                        subtitle={language === 'ru' ? 'Если зависли кнопки' : 'If buttons are frozen'}
                        icon={Trash2}
                        onClick={handlePurgeMemory}
                        colorClass="text-red-500"
                    />
                    <GlassButton
                        title={t('settings_reload', language)}
                        subtitle={language === 'ru' ? 'Сброс кэша и памяти' : 'Clear cache and memory'}
                        icon={RefreshCw}
                        onClick={handleHardReload}
                        colorClass="text-slate-600"
                    />
                </div>

                {/* Logout - Danger Zone */}
                <div className="pt-4">
                    <h3 className="text-[11px] font-bold text-red-400 uppercase tracking-widest ml-4 mb-3">{language === 'ru' ? 'Опасная зона' : 'Danger Zone'}</h3>
                    <button
                        onClick={onLogout}
                        className="w-full py-4 px-6 text-red-500 font-bold bg-white rounded-[20px] flex items-center justify-center gap-2 shadow-sm active:scale-[0.98] transition-transform border border-red-100 hover:bg-red-50"
                    >
                        <LogOut size={20} strokeWidth={2.5} />
                        <span>{t('settings_logout', language)}</span>
                    </button>
                    {onDeleteAccount && (
                        <button
                            onClick={() => setShowDeleteConfirm(true)}
                            className="w-full py-4 px-6 text-red-400 font-bold bg-white rounded-[20px] flex items-center justify-center gap-2 shadow-sm active:scale-[0.98] transition-transform border border-red-50 hover:bg-red-50 mt-3 text-sm"
                        >
                            <UserX size={18} />
                            <span>{language === 'ru' ? 'Удалить аккаунт' : language === 'kz' ? 'Аккаунтты жою' : 'Delete Account'}</span>
                        </button>
                    )}
                </div>

                <p className="text-center text-[10px] text-slate-400 pt-6 font-medium">X5 Marketing v3.1.0</p>
            </div>
        </div>
    );
};

