import React, { useState, useEffect } from 'react';
import { User as UserIcon, Crown, Settings, Zap, History, ChevronRight, Key, LogIn, Briefcase, Trash2, Star, Shield, Pencil, Check, X, Calendar, Plus, FileText, Building2, Camera, Layout, PlayCircle, BookOpen, MessageCircle, Clock, Award, Palette, TrendingUp, BarChart2 } from 'lucide-react';
import { User, Language, HistoryItem, ViewState, UsageState, Platform } from '../types';
import { subscribeToHistory } from '../services/historyService';
import { t } from '../services/translations';
import { getPaymentData } from '../services/paymentService';
import { useToast } from '../components/Toast';
import { supabase } from '../supabase';

// Sub-Views
import { SettingsView } from './SettingsView';
import { SupportView } from './SupportView';
import { LegalView } from './LegalView';
import { ApiManagerView } from './ApiManagerView';
import { PaywallView } from './PaywallView';
import { LanguageView } from './LanguageView';
import { LoginView } from './LoginView';

interface ProfileViewProps {
    user: User;
    onLogout: () => void;
    onDeleteAccount?: () => void | Promise<void>;
    language: Language;
    setLanguage: (lang: Language) => void;
    onUpdateUser?: (user: User) => void;
    onRestoreHistory?: (item: HistoryItem) => void;
    onBack?: () => void;
    onNavigate?: (view: ViewState) => void;
    usage?: UsageState;
    platform?: Platform;
    onPlatformChange?: (platform: Platform) => void;
    onToggleTabBar?: (visible: boolean) => void;
}

export const ProfileView: React.FC<ProfileViewProps> = ({ user, onLogout, onDeleteAccount, language, setLanguage, onRestoreHistory, onNavigate, onUpdateUser, usage, platform = 'web', onPlatformChange, onToggleTabBar }) => {
    const { showToast } = useToast();
    const [currentMode, setCurrentMode] = useState<'profile' | 'settings' | 'languages' | 'status' | 'offer' | 'privacy' | 'contacts' | 'paywall' | 'login'>('profile');
    const [history, setHistory] = useState<HistoryItem[]>([]);
    const [myAd, setMyAd] = useState<any>(null); // State for user's ad
    const [devTapCount, setDevTapCount] = useState(0);
    const [isDevMode, setIsDevMode] = useState(false);

    const [pendingPayment, setPendingPayment] = useState(false);

    // Nickname editing state
    const [isEditingName, setIsEditingName] = useState(false);
    const [newName, setNewName] = useState(user.name);
    const [isEditingNickname, setIsEditingNickname] = useState(false);
    const [newNickname, setNewNickname] = useState(user.nickname || '');
    const [nicknameError, setNicknameError] = useState('');
    const [isEditingBio, setIsEditingBio] = useState(false);
    const [newBio, setNewBio] = useState(user.bio || '');
    const [isEditingServices, setIsEditingServices] = useState(false);
    const [newService, setNewService] = useState('');
    const [services, setServices] = useState<string[]>(user.services || []);

    const handleSaveName = async () => {
        if (!newName.trim() || newName === user.name) {
            setIsEditingName(false);
            setNewName(user.name);
            return;
        }

        const updatedUser = { ...user, name: newName.trim() };

        // Update parent state
        if (onUpdateUser) onUpdateUser(updatedUser);

        // Save to localStorage
        localStorage.setItem('x5_user', JSON.stringify(updatedUser));

        // Save to Supabase
        if (user.id && !user.isGuest) {
            try {
                await supabase.from('profiles').update({ name: newName.trim() }).eq('id', user.id);
            } catch (e) {
                console.error("Failed to save name to Supabase", e);
            }
        }

        setIsEditingName(false);
    };

    const handleSaveNickname = async () => {
        const nick = newNickname.trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
        if (!nick || nick.length < 3) {
            setNicknameError('Минимум 3 символа (a-z, 0-9, _)');
            return;
        }
        if (nick === user.nickname) {
            setIsEditingNickname(false);
            return;
        }

        // Check uniqueness
        if (user.id && !user.isGuest) {
            try {
                const { data: existing } = await supabase
                    .from('profiles')
                    .select('id')
                    .eq('nickname', nick);
                if (existing && existing.length > 0 && existing[0].id !== user.id) {
                    setNicknameError('Этот никнейм уже занят');
                    return;
                }

                await supabase.from('profiles').update({ nickname: nick }).eq('id', user.id);
                const updatedUser = { ...user, nickname: nick };
                if (onUpdateUser) onUpdateUser(updatedUser);
                localStorage.setItem('x5_user', JSON.stringify(updatedUser));
                setNicknameError('');
            } catch (e) {
                console.error("Failed to save nickname", e);
            }
        }

        setIsEditingNickname(false);
    };

    const handleSaveBio = async () => {
        const bio = newBio.trim();
        if (user.id && !user.isGuest) {
            try {
                await supabase.from('profiles').update({ bio }).eq('id', user.id);
                const updatedUser = { ...user, bio };
                if (onUpdateUser) onUpdateUser(updatedUser);
                localStorage.setItem('x5_user', JSON.stringify(updatedUser));
            } catch (e) {
                console.error("Failed to save bio", e);
            }
        }
        setIsEditingBio(false);
    };

    const handleAddService = async () => {
        const svc = newService.trim();
        if (!svc) return;
        const updated = [...services, svc];
        setServices(updated);
        setNewService('');
        if (user.id && !user.isGuest) {
            try {
                await supabase.from('profiles').update({ services: updated }).eq('id', user.id);
                const updatedUser = { ...user, services: updated };
                if (onUpdateUser) onUpdateUser(updatedUser);
                localStorage.setItem('x5_user', JSON.stringify(updatedUser));
            } catch (e) {
                console.error("Failed to save services", e);
            }
        }
    };

    const handleRemoveService = async (idx: number) => {
        const updated = services.filter((_, i) => i !== idx);
        setServices(updated);
        if (user.id && !user.isGuest) {
            try {
                await supabase.from('profiles').update({ services: updated }).eq('id', user.id);
                const updatedUser = { ...user, services: updated };
                if (onUpdateUser) onUpdateUser(updatedUser);
                localStorage.setItem('x5_user', JSON.stringify(updatedUser));
            } catch (e) {
                console.error("Failed to save services", e);
            }
        }
    };

    const handleCancelEdit = () => {
        setNewName(user.name);
        setIsEditingName(false);
    };

    useEffect(() => {
        const devStatus = localStorage.getItem('x5_dev_mode') === 'true';
        setIsDevMode(devStatus);

        if (user?.id && !user.isGuest) {
            // 1. Subscribe to History
            const unsubscribeHistory = subscribeToHistory(user.id, 'all', (items) => {
                setHistory(items);
            });

            // 2. Fetch User's Ad (Specialist Profile)
            const fetchMyAd = async () => {
                try {
                    const { data, error } = await supabase
                        .from('specialists')
                        .select('*')
                        .eq('user_id', user.id)
                        .maybeSingle();
                    if (!error && data) {
                        setMyAd(data);
                    } else {
                        setMyAd(null);
                    }
                } catch (e) {
                    console.error("Error fetching ad", e);
                }
            };
            fetchMyAd();

            return () => unsubscribeHistory();
        }
    }, [user?.id, currentMode]);

    // Handle Tab Bar Visibility based on mode
    useEffect(() => {
        if (onToggleTabBar) {
            // Show dock ONLY when in main 'profile' screen
            onToggleTabBar(currentMode === 'profile');
        }
        return () => {
            // Safety: restore dock when unmounting (leaving profile view entirely)
            if (onToggleTabBar) onToggleTabBar(true);
        };
    }, [currentMode, onToggleTabBar]);

    // Native auth flow updates App-level user via Supabase listener, not LoginView onLogin callback.
    // Ensure we leave the login modal as soon as the user is authenticated.
    useEffect(() => {
        if (user.isGuest || currentMode !== 'login') return;
        if (pendingPayment) {
            setPendingPayment(false);
            setCurrentMode('paywall');
            return;
        }
        setCurrentMode('profile');
    }, [user.isGuest, currentMode, pendingPayment]);

    const handleDevTap = () => {
        const newCount = devTapCount + 1;
        setDevTapCount(newCount);
        if (navigator.vibrate) navigator.vibrate(50);
        if (newCount >= 10) {
            setCurrentMode('status');
            setDevTapCount(0);
        }
    };

    const handleBuyCredits = () => {
        const { action, params } = getPaymentData(100, user.email);
        const form = document.createElement('form');
        form.method = 'POST';
        form.action = action;
        form.enctype = 'multipart/form-data';
        Object.entries(params).forEach(([key, value]) => {
            const input = document.createElement('input');
            input.type = 'hidden';
            input.name = key;
            input.value = value;
            form.appendChild(input);
        });
        document.body.appendChild(form);
        form.submit();
        document.body.removeChild(form);
    };



    const handlePaymentAccess = () => {
        if (user.isGuest) {
            setPendingPayment(true);
            setCurrentMode('login');
        } else {
            setCurrentMode('paywall');
        }
    };

    const handleDeleteAd = async () => {
        if (!user?.id) return;
        if (confirm(t('profile_delete_confirm', language))) {
            try {
                await supabase.from('specialists').delete().eq('user_id', user.id);
                setMyAd(null);
            } catch (e) {
                showToast(t('profile_delete_error', language), 'error');
            }
        }
    };

    const getIconForType = (type: string) => {
