import React, { useState, useEffect, useCallback, memo, useRef } from 'react';
import { Home, GraduationCap, User as UserIcon, MessageCircle, LogOut, Zap, BarChart2, Briefcase, MessageSquare, Plus, Sparkles, Grid3X3 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { DesignView } from './views/DesignView';
import { PhotoView } from './views/PhotoView';
import { ContractView } from './views/ContractView';
import { VideoCreativeView } from './views/VideoCreativeView';
import { ProjectsHistoryView } from './views/ProjectsHistoryView';
import { CoursesView } from './views/CoursesView';
import { MyCoursesView } from './views/MyCoursesView';
import { ProfileView } from './views/ProfileView';
import { HomeView } from './views/HomeView';
import { AdminView } from './views/AdminView';
import { AdminApiKeyView } from './views/AdminApiKeyView';
import { AllTechView } from './views/AllTechView';
import { LanguageView } from './views/LanguageView';
import { ChatView } from './views/ChatView';
import { InstagramView } from './views/InstagramView';
import { VideoGenView } from './views/VideoGenView';
import { SuccessView } from './views/SuccessView';
import { MockPaymentView } from './views/MockPaymentView';
import { AnalyticsView } from './views/AnalyticsView';
import { HireView } from './views/HireView';
import { ChatsListView } from './views/ChatsListView';
import { PaywallView } from './views/PaywallView';
import { CourseEditorView } from './views/CourseEditorView';
import { WhatsAppBotView } from './views/WhatsAppBotView';
import { RedirectView } from './views/RedirectView';
import { BusinessLandingView } from './views/BusinessLandingView';
import { CRMView } from './views/CRMView';
import { ViewState, User, Language, HistoryItem, AppConfig, ChatMessage, UsageState, Course, Platform, Specialist } from './types';
import { supabase } from './supabase';
import { detectPlatform } from './utils/platformUtils';
import { t } from './services/translations';
import { useToast } from './components/Toast';
import { useConfirmDialog } from './components/ConfirmDialog';
import { startPresenceTracking, stopPresenceTracking } from './services/presenceService';
import { showNotification } from './services/notificationService';

const defaultConfig: AppConfig = {
    photo: true,
    design: true,
    contract: true,
    video: true,
    courses: true
};

const MAIN_TABS: ViewState[] = ['home', 'courses', 'hire', 'chats_list', 'profile'];

const GUEST_USER: User = {
    id: 'guest',
    name: 'Гость',
    isGuest: true,
    plan: 'free',
    credits: 0
};

type NativeAuthProvider = 'apple' | 'google' | 'email';

type NativeAuthResultPayload = {
    success: boolean;
    provider?: NativeAuthProvider;
    accessToken?: string;
    refreshToken?: string;
    error?: string;
    canceled?: boolean;
    cancelled?: boolean;
};

type NativeAuthBootstrapPayload = {
    id: string;
    name?: string;
    email?: string;
    avatar?: string;
    isGuest?: boolean;
    plan?: 'free' | 'pro' | 'black';
    credits?: number;
    purchasedCourseIds?: string[];
    subscriptionDate?: string;
    subscriptionEndDate?: string;
    subscriptionType?: 'monthly' | 'yearly';
    purchaseHistory?: any[];
};

type NativePaymentResultPayload = {
    success: boolean;
    productId?: string;
    canceled?: boolean;
    cancelled?: boolean;
    error?: string;
    isActive?: boolean;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
    typeof value === 'object' && value !== null;

const parseEventDetail = (rawDetail: unknown): unknown => {
    if (typeof rawDetail !== 'string') return rawDetail;
    try {
        return JSON.parse(rawDetail);
    } catch {
        return null;
    }
};

const parseNativeAuthResult = (rawDetail: unknown): NativeAuthResultPayload | null => {
    const detail = parseEventDetail(rawDetail);
    if (!isRecord(detail)) return null;
    if (typeof detail.success !== 'boolean') return null;

    if (
        detail.provider !== undefined &&
        detail.provider !== 'apple' &&
        detail.provider !== 'google' &&
        detail.provider !== 'email'
    ) {
        return null;
    }

    if (detail.accessToken !== undefined && typeof detail.accessToken !== 'string') return null;
    if (detail.refreshToken !== undefined && typeof detail.refreshToken !== 'string') return null;
    if (detail.error !== undefined && typeof detail.error !== 'string') return null;
    if (detail.canceled !== undefined && typeof detail.canceled !== 'boolean') return null;
    if (detail.cancelled !== undefined && typeof detail.cancelled !== 'boolean') return null;

    return detail as NativeAuthResultPayload;
};

const parseNativeAuthBootstrap = (rawDetail: unknown): NativeAuthBootstrapPayload | null => {
    const detail = parseEventDetail(rawDetail);
    if (!isRecord(detail)) return null;
    if (typeof detail.id !== 'string' || !detail.id) return null;
    if (detail.name !== undefined && typeof detail.name !== 'string') return null;
    if (detail.email !== undefined && typeof detail.email !== 'string') return null;
    if (detail.avatar !== undefined && typeof detail.avatar !== 'string') return null;
    if (detail.isGuest !== undefined && typeof detail.isGuest !== 'boolean') return null;
    if (detail.credits !== undefined && typeof detail.credits !== 'number') return null;
    if (detail.purchasedCourseIds !== undefined && !Array.isArray(detail.purchasedCourseIds)) return null;
    return detail as NativeAuthBootstrapPayload;
};

const parseNativePaymentResult = (rawDetail: unknown): NativePaymentResultPayload | null => {
    const detail = parseEventDetail(rawDetail);
    if (!isRecord(detail)) return null;
    if (typeof detail.success !== 'boolean') return null;
    if (detail.productId !== undefined && typeof detail.productId !== 'string') return null;
    if (detail.error !== undefined && typeof detail.error !== 'string') return null;
    if (detail.canceled !== undefined && typeof detail.canceled !== 'boolean') return null;
    if (detail.cancelled !== undefined && typeof detail.cancelled !== 'boolean') return null;
    if (detail.isActive !== undefined && typeof detail.isActive !== 'boolean') return null;
    return detail as NativePaymentResultPayload;
};

const Background = memo(({ view }: { view: ViewState }) => {
    const isHome = view === 'home';
    return (
        <div className={`liquid-bg ${isHome ? 'orange-theme' : ''}`}>
            <div className={`liquid-blob ${isHome ? 'blob-orange-1' : 'blob-1'}`}></div>
            <div className={`liquid-blob ${isHome ? 'blob-orange-2' : 'blob-2'}`}></div>
            <div className={`liquid-blob ${isHome ? 'blob-orange-3' : 'blob-3'}`}></div>
        </div>
    );
});

function App() {
    const { showToast } = useToast();
    const { confirm } = useConfirmDialog();

    // Check for redirect URL (/r/:shortCode)
    const [redirectShortCode, setRedirectShortCode] = useState<string | null>(() => {
        const path = window.location.pathname;
        if (path.startsWith('/r/')) {
            return path.substring(3); // Extract shortCode
        }
        return null;
    });

    // Check for invite URL (/invite/:code)
    const [inviteCode, setInviteCode] = useState<string | null>(() => {
        const path = window.location.pathname;
        if (path.startsWith('/invite/')) {
            return path.substring(8); // Extract invite code
        }
        return null;
    });

    // If we have a redirect shortCode, render the redirect view
    if (redirectShortCode) {
        return <RedirectView shortCode={redirectShortCode} />;
    }

    // Store toast function in ref for use in window callbacks
    const showToastRef = useRef(showToast);
    useEffect(() => {
        showToastRef.current = showToast;
    }, [showToast]);

    const [user, setUser] = useState<User>(() => {
        const saved = localStorage.getItem('x5_user');
        if (saved) {
            try {
                const parsed = JSON.parse(saved);
                return { ...parsed, plan: parsed.plan || 'free', credits: parsed.credits || 0 };
            } catch (e) { }
        }
        return GUEST_USER;
    });

    // Ref to always have current user in callbacks (fixes stale closure)
    const userRef = useRef(user);
    useEffect(() => {
        userRef.current = user;
    }, [user]);
    const nativeAuthLockUntilRef = useRef(0);
    const googleNativeRetryRef = useRef(0);

    const [loading, setLoading] = useState(true);
    const [currentView, setCurrentView] = useState<ViewState>('home');
    const [initialPrompt, setInitialPrompt] = useState<string>('');
    const [transitionClass, setTransitionClass] = useState('animate-fade-in');
    const [navigationPayload, setNavigationPayload] = useState<any>(null);
    const [isTabBarVisible, setIsTabBarVisible] = useState(true);
    const [tabBarHiddenByScroll, setTabBarHiddenByScroll] = useState(false);
    const lastScrollY = React.useRef(0);

    const [platform, setPlatform] = useState<Platform>(() => {
        const override = localStorage.getItem('x5_platform_override') as Platform | null;
        return override || detectPlatform();
    });

    useEffect(() => {
        const detected = detectPlatform();
        const override = localStorage.getItem('x5_platform_override') as Platform | null;
        const nextPlatform = override || detected;
        setPlatform((prev) => (prev === nextPlatform ? prev : nextPlatform));
    }, []);

    const handlePlatformChange = (newPlatform: Platform) => {
        setPlatform(newPlatform);
        localStorage.setItem('x5_platform_override', newPlatform);
    };

    const [language, setLanguage] = useState<Language>(() => {
        const saved = localStorage.getItem('x5_language');
        return (saved as Language) || 'ru';
    });

    const [usage, setUsage] = useState<UsageState>({ guestStandardCount: 0, proCount: 0 });
    const [config, setConfig] = useState<AppConfig>(() => {
        const saved = localStorage.getItem('x5_config');
        return saved ? JSON.parse(saved) : defaultConfig;
    });

    const [pendingCourse, setPendingCourse] = useState<Course | null>(null);

    // CHAT STATE
    const [activeSpecialist, setActiveSpecialist] = useState<Specialist | null>(null);
    const [chatsList, setChatsList] = useState<any[]>([]);

    // Hide TabBar on scroll down, show on scroll up
    useEffect(() => {
        let ticking = false;

        const handleScroll = () => {
            if (!ticking) {
                window.requestAnimationFrame(() => {
                    const currentScrollY = window.scrollY;
                    const scrollingDown = currentScrollY > lastScrollY.current && currentScrollY > 50;
                    const scrollingUp = currentScrollY < lastScrollY.current;

                    if (scrollingDown) {
                        setTabBarHiddenByScroll(true);
                    } else if (scrollingUp) {
                        setTabBarHiddenByScroll(false);
                    }

                    lastScrollY.current = currentScrollY;
                    ticking = false;
                });
                ticking = true;
            }
        };

        // Also listen to scroll events on scrollable containers
        const handleElementScroll = (e: Event) => {
            const target = e.target as HTMLElement;
            if (!target || !target.scrollTop) return;

            const currentScrollY = target.scrollTop;
            const prevScrollY = (target as any).__prevScrollY || 0;

            if (currentScrollY > prevScrollY && currentScrollY > 50) {
                setTabBarHiddenByScroll(true);
            } else if (currentScrollY < prevScrollY) {
                setTabBarHiddenByScroll(false);
            }

            (target as any).__prevScrollY = currentScrollY;
        };

        window.addEventListener('scroll', handleScroll, { passive: true });
        document.addEventListener('scroll', handleElementScroll, { passive: true, capture: true });

        return () => {
            window.removeEventListener('scroll', handleScroll);
            document.removeEventListener('scroll', handleElementScroll, true);
        };
    }, []);

    // Push notifications are handled by Expo native layer
    // Web notifications will be handled via Supabase realtime

    // If we're processing an invite, show loading
    if (inviteCode && !user.isGuest && loading) {
        return (
            <div className="w-full h-[100dvh] bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="bg-white rounded-[32px] p-8 shadow-2xl max-w-sm w-full mx-4 text-center">
                    <div className="w-20 h-20 rounded-full bg-gradient-to-br from-green-500 to-green-600 mx-auto mb-6 flex items-center justify-center">
                        <svg className="w-10 h-10 text-white animate-spin" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                            <path className="opacity-75" fill="currentColor" d="m4 12a8 8 0 0 1 8-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 0 1 4 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                        </svg>
                    </div>
                    <h2 className="text-2xl font-black text-slate-900 mb-2">Активация ссылки...</h2>
                    <p className="text-sm text-slate-500">Добавляем курс в ваш аккаунт</p>
                </div>
            </div>
        );
    }

    // --- SWIPE LOGIC DISABLED ---
    const onTouchStart = () => {};
    const onTouchMove = () => {};
    const onTouchEnd = () => {};

    // === INVITE LINK HANDLER ===
    const handleInviteCode = async (code: string) => {
        if (!user || user.isGuest) {
            showToast('Войдите в аккаунт для использования инвайт-ссылки', 'warning');
            return;
        }

        setLoading(true);
        try {
            // 1. Найти инвайт по code в Supabase
            const { data: invites, error: inviteError } = await supabase
                .from('course_invites')
                .select('*')
                .eq('code', code)
                .limit(1);

            if (inviteError || !invites || invites.length === 0) {
                showToast('Инвайт-ссылка не найдена', 'error');
                return;
            }

            const invite = invites[0] as any;

            // 2. Проверки: active, не истёк, не превышен maxUses
            if (!invite.active) {
                showToast('Инвайт-ссылка деактивирована', 'error');
                return;
            }

            if (invite.expiresAt && new Date(invite.expiresAt) < new Date()) {
                showToast('Срок действия ссылки истёк', 'error');
                return;
            }

            if (invite.maxUses && invite.usedCount >= invite.maxUses) {
                showToast('Лимит использований исчерпан', 'error');
                return;
            }

            // Проверка: уже использована этим пользователем
            if (invite.usedBy && invite.usedBy.includes(user.id)) {
                showToast('Вы уже использовали эту ссылку', 'error');
                // Всё равно редиректим на курс
                handleNavigate('courses');
                return;
            }

            // Проверка: уже куплен
            if (user.purchasedCourseIds?.includes(invite.courseId)) {
                showToast('Курс уже приобретён', 'info');
                handleNavigate('courses');
                return;
            }

            // 3. Добавить courseId в user.purchasedCourseIds
            const newPurchases = [...(user.purchasedCourseIds || []), invite.courseId];
            const updatedUser = {
                ...user,
                purchasedCourseIds: newPurchases
            };

            // 4. Обновить invite: увеличить usedCount, добавить userId в usedBy
            const newUsedBy = [...(invite.usedBy || []), user.id];
            const newUsedCount = invite.usedCount + 1;
            const updateData: any = {
                usedCount: newUsedCount,
                usedBy: newUsedBy
            };

            // 5. Если type=single → поставить active=false
            if (invite.type === 'single') {
                updateData.active = false;
            }

            // Выполнить обновления в Supabase
            await Promise.all([
                supabase.from('profiles').update({
                    purchased_course_ids: newPurchases
                }).eq('id', user.id),
                supabase.from('course_invites').update(updateData).eq('id', invite.id)
            ]);

            // Обновить локальное состояние
            setUser(updatedUser);
            localStorage.setItem('x5_user', JSON.stringify(updatedUser));

            showToast('Курс успешно добавлен!', 'success');

            // 6. Редирект на курсы
            handleNavigate('courses');
        } catch (error) {
            console.error('Invite processing error:', error);
            showToast('Ошибка обработки инвайт-ссылки', 'error');
        } finally {
            setLoading(false);
            // Очистить URL
            window.history.replaceState({}, '', '/');
            setInviteCode(null);
        }
    };

    // Обработать инвайт-код при загрузке
    useEffect(() => {
        if (inviteCode && !user.isGuest) {
            handleInviteCode(inviteCode);
        }
    }, [inviteCode, user.isGuest]);

    useEffect(() => {
        const memoryInterval = setInterval(() => {
            if ((window as any).gc) {
                try { (window as any).gc(); } catch (e) { /* ignore */ }
            }
        }, 2000);
        return () => clearInterval(memoryInterval);
    }, []);

    // --- NATIVE BRIDGE LISTENER ---
    useEffect(() => {
        // --- GLOBAL FLUTTER LISTENERS ---
        (window as any).onAppPaymentSuccess = (productId: string) => {
            const currentUser = userRef.current; // Use ref for fresh data
            showToastRef.current("Оплата прошла успешно!", "success");
            console.log("[App] onAppPaymentSuccess called with:", productId, "user:", currentUser);

            // Check if user already has active subscription
            const hasActiveSubscription = currentUser.plan === 'pro' &&
                currentUser.subscriptionEndDate &&
                new Date(currentUser.subscriptionEndDate) > new Date();

            let newCreditsReward = 0;
            let newPlan: 'free' | 'pro' | 'black' | undefined = undefined;
            let subscriptionDurationMonths = 0;
            let newSubscriptionType: 'monthly' | 'yearly' | undefined = undefined;
            let purchaseAmount = 0;

            if (productId === 'x5_credits_1000') {
                // Credits purchase - always give credits
                newCreditsReward = 1000;
                purchaseAmount = 9;
            } else if (productId === 'x5_pro_monthly') {
                // Monthly subscription - only give credits if NOT already subscribed
                if (!hasActiveSubscription) {
                    newCreditsReward = 1000;
                }
                newPlan = 'pro';
                newSubscriptionType = 'monthly';
                subscriptionDurationMonths = 1;
                purchaseAmount = 19;
            } else if (productId === 'x5_pro_yearly') {
                // Yearly subscription - only give credits if NOT already subscribed OR upgrading from monthly
                const isUpgrade = hasActiveSubscription && currentUser.subscriptionType === 'monthly';
                if (!hasActiveSubscription || isUpgrade) {
                    newCreditsReward = 12000;
                }
                newPlan = 'pro';
                newSubscriptionType = 'yearly';
                subscriptionDurationMonths = 12;
                purchaseAmount = 199;
            } else {
                // Fallback for legacy ID - only give credits if NOT already subscribed
                if (!hasActiveSubscription) {
                    newCreditsReward = 1000;
                }
                newPlan = 'pro';
                newSubscriptionType = 'monthly';
                subscriptionDurationMonths = 1;
                purchaseAmount = 19;
            }

            // Calculate new subscription end date
            let newSubscriptionEndDate = currentUser.subscriptionEndDate ? new Date(currentUser.subscriptionEndDate) : new Date();
            // If expired, start from now
            if (newSubscriptionEndDate < new Date()) {
                newSubscriptionEndDate = new Date();
            }
            if (subscriptionDurationMonths > 0) {
                newSubscriptionEndDate.setMonth(newSubscriptionEndDate.getMonth() + subscriptionDurationMonths);
            }

            // Create purchase record
            const purchaseRecord = {
                productId,
                purchaseDate: new Date().toISOString(),
                amount: purchaseAmount,
                currency: 'USD'
            };

            const updatedUser: User = {
                ...currentUser,
                credits: (currentUser.credits || 0) + newCreditsReward,
                plan: newPlan || currentUser.plan,
                subscriptionDate: newPlan === 'pro' ? (currentUser.subscriptionDate || new Date().toISOString()) : currentUser.subscriptionDate,
                subscriptionEndDate: subscriptionDurationMonths > 0 ? newSubscriptionEndDate.toISOString() : currentUser.subscriptionEndDate,
                subscriptionType: newSubscriptionType || currentUser.subscriptionType,
                purchaseHistory: [...(currentUser.purchaseHistory || []), purchaseRecord]
            };

            setUser(updatedUser);
            localStorage.setItem('x5_credits', updatedUser.credits.toString());
            localStorage.setItem('x5_user', JSON.stringify(updatedUser));

            // Atomic credit addition via Supabase RPC + profile update
            if (newCreditsReward > 0) {
                (async () => {
                    try {
                        const { error } = await supabase.rpc('add_credits', { user_id: currentUser.id, amount: newCreditsReward });
                        if (error) throw error;
                    } catch (e) {
                        console.error("Supabase add_credits failed", e);
                    }
                })();
            }
            supabase.from('profiles').update({
                plan: updatedUser.plan,
                subscription_date: updatedUser.subscriptionDate,
                subscription_end_date: updatedUser.subscriptionEndDate,
                subscription_type: updatedUser.subscriptionType,
            }).eq('id', currentUser.id).then(({ error }) => {
                if (error) {
                    console.error("Supabase profile update failed", error);
                    showToastRef.current("Ошибка сохранения оплаты", "error");
                }
            });

            setCurrentView('success');
            setPendingCourse(null);
        };

        (window as any).onAppPaymentFailed = (error: string) => {
            showToastRef.current("Ошибка оплаты: " + error, "error");
        };

        // --- EXPO NATIVE AUTH LISTENER (Supabase token from Apple/Google Sign-In) ---
        const triggerNativeGoogleLogin = () => {
            try {
                const msg = JSON.stringify({ type: 'LOGIN_GOOGLE' });
                if ((window as any).ReactNativeWebView?.postMessage) {
                    (window as any).ReactNativeWebView.postMessage(msg);
                    return;
                }
                if ((window as any).flutter_inappwebview?.callHandler) {
                    (window as any).flutter_inappwebview.callHandler('nativeBridge', msg);
                    return;
                }
                if ((window as any).webkit?.messageHandlers?.x5App) {
                    (window as any).webkit.messageHandlers.x5App.postMessage({ type: 'LOGIN_GOOGLE' });
                }
            } catch (error) {
                console.warn('[App] Native Google retry send failed', error);
            }
        };

        const handleNativeAuth = async (e: Event) => {
            const detail = parseNativeAuthResult((e as CustomEvent).detail);
            if (!detail) return;
            // Old native build dispatches appleSignInResult for non-Apple providers too.
            // Ignore duplicated non-Apple payloads from that channel.
            if (e.type === 'appleSignInResult' && detail.provider && detail.provider !== 'apple') return;

            const applyNativeAuthUser = async (accessToken: string) => {
                try {
                    const { data: authData, error: authError } = await supabase.auth.getUser(accessToken);
                    if (authError || !authData?.user) return;

                    const authUser = authData.user;
                    const { data: profile } = await supabase
                        .from('profiles')
                        .select('*')
                        .eq('id', authUser.id)
                        .maybeSingle();

                    const forcedUser: User = {
                        id: authUser.id,
                        name:
                            profile?.name ||
                            authUser.user_metadata?.full_name ||
                            authUser.user_metadata?.name ||
                            authUser.email?.split('@')[0] ||
                            'User',
                        email: authUser.email || undefined,
                        avatar: profile?.avatar || authUser.user_metadata?.avatar_url || undefined,
                        isGuest: false,
                        plan: profile?.plan || 'free',
                        credits: (profile?.credits ?? parseInt(localStorage.getItem('x5_credits') || '0', 10)) || 0,
                        purchasedCourseIds: profile?.purchased_course_ids || [],
                        subscriptionDate: profile?.subscription_date || undefined,
                        subscriptionEndDate: profile?.subscription_end_date || undefined,
                        subscriptionType: profile?.subscription_type || undefined,
                        purchaseHistory: profile?.purchase_history || [],
                    };

                    setUser(forcedUser);
                    localStorage.setItem('x5_user', JSON.stringify(forcedUser));
                    localStorage.setItem('x5_credits', String(forcedUser.credits || 0));
                } catch {
                    // no-op fallback
                }
            };

            if (detail.success && detail.accessToken) {
                if (detail.provider === 'google') {
                    googleNativeRetryRef.current = 0;
                }
                nativeAuthLockUntilRef.current = Date.now() + 10_000;
                try {
                    if (detail.refreshToken) {
                        const { error } = await supabase.auth.setSession({
                            access_token: detail.accessToken,
                            refresh_token: detail.refreshToken,
                        });
                        if (error) throw error;
                    }
                    await applyNativeAuthUser(detail.accessToken);
                    setCurrentView('home');
                    setLoading(false);
                    // onAuthStateChange will handle the rest (load profile, update state)
                } catch (err: any) {
                    console.error('[App] Failed to set Supabase session from native:', err);
                    await applyNativeAuthUser(detail.accessToken);
                    setCurrentView('home');
                    setLoading(false);
                    showToastRef.current('Ошибка: ' + (err?.message || err), 'error');
                }
            } else if (detail.canceled || detail.cancelled) {
                showToastRef.current('Вход отменен', 'info');
            } else if (detail.error) {
                const lowerError = detail.error.toLowerCase();
                const isGoogleNotReady =
                    detail.provider === 'google' &&
                    lowerError.includes('cannot prompt to authenticate until the request has finished loading');

                if (isGoogleNotReady && googleNativeRetryRef.current < 3) {
                    googleNativeRetryRef.current += 1;
                    const attempt = googleNativeRetryRef.current;
                    const waitMs = 700 * attempt;
                    showToastRef.current('Google auth initializing... retry ' + attempt + '/3', 'info');
                    setTimeout(triggerNativeGoogleLogin, waitMs);
                    return;
                }

                showToastRef.current('Ошибка входа: ' + detail.error, 'error');
            }
        };
        window.addEventListener('appleSignInResult', handleNativeAuth);
        window.addEventListener('nativeAuthResult', handleNativeAuth);

        const handleNativeAuthBootstrap = (e: Event) => {
            const detail = parseNativeAuthBootstrap((e as CustomEvent).detail);
            if (!detail) return;
            const forcedUser: User = {
                id: detail.id,
                name: detail.name || 'User',
                email: detail.email,
                avatar: detail.avatar,
                isGuest: false,
                plan: detail.plan || 'free',
                credits: detail.credits ?? 0,
                purchasedCourseIds: detail.purchasedCourseIds || [],
                subscriptionDate: detail.subscriptionDate,
                subscriptionEndDate: detail.subscriptionEndDate,
                subscriptionType: detail.subscriptionType,
                purchaseHistory: detail.purchaseHistory || [],
            };
            setUser(forcedUser);
            localStorage.setItem('x5_user', JSON.stringify(forcedUser));
            localStorage.setItem('x5_credits', String(forcedUser.credits || 0));
        };
        window.addEventListener('x5NativeAuthBootstrap', handleNativeAuthBootstrap);

        // --- EXPO NATIVE PAYMENT RESULT LISTENER ---
        const handleNativePaymentResult = (e: Event) => {
            const detail = parseNativePaymentResult((e as CustomEvent).detail);
            if (!detail) return;

            if (detail.success) {
                const productId = detail.productId || 'x5_pro_monthly';
                if ((window as any).onAppPaymentSuccess) {
                    (window as any).onAppPaymentSuccess(productId);
                }
                return;
            }

            if (detail.cancelled || detail.canceled) {
                showToastRef.current('Payment cancelled', 'info');
                return;
            }

            const errorMessage = detail.error || 'Payment failed';
            if ((window as any).onAppPaymentFailed) {
                (window as any).onAppPaymentFailed(errorMessage);
            } else {
                showToastRef.current(`Payment failed: ${errorMessage}`, 'error');
            }
        };
        window.addEventListener('paymentResult', handleNativePaymentResult);

        // --- NATIVE MESSAGE HANDLER (postMessage from Expo WebView) ---
        const handleNativeMessage = (event: MessageEvent) => {
            let data = event.data;
            if (typeof data === 'string') {
                try { data = JSON.parse(data); } catch (e) { /* ignore */ }
            }

            if (data?.type === 'NAVIGATION') {
                const target = data.payload?.view;
                if (target) {
                    handleNavigate(target);
                }
            }
        };

        window.addEventListener('message', handleNativeMessage);

        // Cleanup function
        return () => {
            window.removeEventListener('message', handleNativeMessage);
            window.removeEventListener('appleSignInResult', handleNativeAuth);
            window.removeEventListener('nativeAuthResult', handleNativeAuth);
            window.removeEventListener('x5NativeAuthBootstrap', handleNativeAuthBootstrap);
            window.removeEventListener('paymentResult', handleNativePaymentResult);
            delete (window as any).onAppPaymentSuccess;
            delete (window as any).onAppPaymentFailed;
        };
    }, []); // Run once on mount (callbacks use closure for latest state)

    // --- REAL CHAT LISTENER (Supabase) ---
    const loadChats = useCallback(async (userId: string) => {
        const { data: chats } = await supabase
            .from('chats')
            .select('*')
            .contains('participants', [userId])
            .order('last_message_at', { ascending: false });

        if (!chats) { setChatsList([]); return; }

        const loadedChats = await Promise.all(chats.map(async (chat: any) => {
            const otherUserId = chat.participants.find((id: string) => id !== userId);
            if (!otherUserId) return null;

            let profile = { name: 'Пользователь', avatar: '', role: 'Client' };
            try {
                const { data: spec } = await supabase.from('specialists').select('name, avatar, role').eq('user_id', otherUserId).single();
                if (spec) {
                    profile = { name: spec.name || 'Специалист', avatar: spec.avatar || '', role: spec.role || 'Исполнитель' };
                } else {
                    const { data: prof } = await supabase.from('profiles').select('name, avatar').eq('id', otherUserId).single();
                    if (prof) {
                        profile = { name: prof.name || 'Клиент', avatar: prof.avatar || '', role: 'Заказчик' };
                    }
                }
            } catch (e) { /* ignore */ }

            const unreadCount = chat.unread_count ? (chat.unread_count[userId] || 0) : 0;
            const ts = chat.last_message_at ? new Date(chat.last_message_at).getTime() : 0;

            return {
                id: chat.id,
                timestamp: ts,
                lastMessage: chat.last_message || 'Вложение',
                time: chat.last_message_at ? new Date(chat.last_message_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '',
                unread: unreadCount,
                specialist: {
                    id: otherUserId,
                    name: profile.name,
                    role: profile.role,
                    avatar: profile.avatar,
                    rating: 5.0,
                    price: '',
                    skills: [],
                    online: true
                }
            };
        }));

        const validChats = loadedChats.filter((c): c is any => c !== null);
        const dedupMap = new Map<string, any>();
        for (const c of validChats) {
            const key = c.specialist.id;
            const existing = dedupMap.get(key);
            if (!existing || c.timestamp > existing.timestamp) {
                dedupMap.set(key, c);
            }
        }
        setChatsList(Array.from(dedupMap.values()).sort((a, b) => b.timestamp - a.timestamp));
    }, []);

    useEffect(() => {
        if (!user?.id || user.id === 'guest') {
            setChatsList([]);
            return;
        }

        // Initial load
        loadChats(user.id);

        // Realtime subscription
        const channel = supabase.channel('chats_' + user.id)
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'chats',
            }, () => {
                loadChats(user.id);
            })
            .subscribe();

        return () => { supabase.removeChannel(channel); };
    }, [user?.id, loadChats]);

    useEffect(() => {
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('status') === 'success') {
            window.history.replaceState({}, '', window.location.pathname);
            setCurrentView('success');
        }

        localStorage.setItem('x5_language', language);

        const storedUsage = localStorage.getItem('x5_usage');
        if (storedUsage) setUsage(JSON.parse(storedUsage));

        // Supabase auth state listener
        const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
            if (session?.user) {
                nativeAuthLockUntilRef.current = 0;
                const userId = session.user.id;
                const isAnon = session.user.is_anonymous || false;

                // Load profile from Supabase
                let profile: any = {};
                try {
                    const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();
                    if (data) profile = data;
                } catch (e) { console.log("Error fetching profile"); }

                const storedCredits = parseInt(localStorage.getItem('x5_credits') || '0', 10);

                const newUser: User = {
                    id: userId,
                    name: profile.name || session.user.user_metadata?.full_name || session.user.email?.split('@')[0] || (isAnon ? 'Гость' : 'Пользователь'),
                    email: session.user.email || undefined,
                    avatar: profile.avatar || session.user.user_metadata?.avatar_url || undefined,
                    isGuest: isAnon,
                    nickname: profile.nickname || undefined,
                    bio: profile.bio || undefined,
                    services: profile.services || undefined,
                    createdAt: profile.created_at || undefined,
                    isCompany: profile.is_company || false,
                    companyName: profile.company_name || undefined,
                    plan: profile.plan || 'free',
                    credits: isAnon ? 0 : (profile.credits ?? storedCredits ?? 0),
                    purchasedCourseIds: profile.purchased_course_ids || [],
                    subscriptionDate: profile.subscription_date || undefined,
                    subscriptionEndDate: profile.subscription_end_date || undefined,
                    subscriptionType: profile.subscription_type || undefined,
                    purchaseHistory: profile.purchase_history || []
                };

                setUser(newUser);
                localStorage.setItem('x5_user', JSON.stringify(newUser));
                localStorage.setItem('x5_credits', String(newUser.credits));

                // Upsert profile (create if not exists)
                supabase.from('profiles').upsert({
                    id: userId,
                    name: newUser.name,
                    avatar: newUser.avatar || '',
                    email: newUser.email || '',
                    is_guest: isAnon,
                }, { onConflict: 'id' }).then(() => {});

                // Start presence tracking for real users
                if (!isAnon) {
                    startPresenceTracking(userId);
                }
            } else {
                if (Date.now() < nativeAuthLockUntilRef.current) {
                    setLoading(false);
                    return;
                }
                // Not logged in
                stopPresenceTracking();
                setUser(GUEST_USER);
            }
            setLoading(false);
        });

        return () => {
            subscription.unsubscribe();
            stopPresenceTracking();
        };
    }, [language]);

    // Listen for native tab navigation from Expo WebView
    useEffect(() => {
        const handler = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            if (detail?.view) {
                handleNavigate(detail.view as ViewState);
            }
        };
        window.addEventListener('x5NativeNavigate', handler);
        return () => window.removeEventListener('x5NativeNavigate', handler);
    }, []);

    const handleNavigate = useCallback((view: ViewState, payload?: any) => {
        const prevIndex = MAIN_TABS.indexOf(currentView);
        const nextIndex = MAIN_TABS.indexOf(view);

        // Logic:
        // 1. Tab <-> Tab: Use index comparison
        // 2. Tab -> Detail: Slide Right (Enter "Forward")
        // 3. Detail -> Tab: Slide Left (Enter "Back")
        // 4. Detail -> Detail: Slide Right ("Forward") - default assumption

        let newTransition = 'animate-fade-in';

        if (prevIndex !== -1 && nextIndex !== -1) {
            // Both are main tabs — instant fade (no slide)
            newTransition = 'animate-fade-in';
        } else if (prevIndex !== -1 && nextIndex === -1) {
            // Tab -> Detail
            newTransition = 'animate-slide-enter-right';
        } else if (prevIndex === -1 && nextIndex !== -1) {
            // Detail -> Tab
            newTransition = 'animate-slide-enter-left';
        } else {
            // Detail -> Detail
            newTransition = 'animate-slide-enter-right';
        }

        setTransitionClass(newTransition);
        setNavigationPayload(payload || null);
        setInitialPrompt('');
        setIsTabBarVisible(true);

        if (view === 'chat') {
            if (payload && (payload as Specialist).id) {
                setActiveSpecialist(payload as Specialist);
                setIsTabBarVisible(false);
            } else {
                setActiveSpecialist(null);
            }
        } else {
            if (currentView === 'chat') {
                setIsTabBarVisible(true);
            }
        }

        setCurrentView(view);
    }, [currentView]);

    const handleLogin = (newUser: User) => {
        const upgradedUser = { ...newUser, plan: 'free' as const, credits: 0, purchasedCourseIds: [] };
        setUser(upgradedUser);
        localStorage.setItem('x5_user', JSON.stringify(upgradedUser));
        setCurrentView('home');
    };

    const handleUpdateUser = (updatedUser: User) => {
        console.log("[App] handleUpdateUser called:", updatedUser);
        setUser(updatedUser);
        localStorage.setItem('x5_user', JSON.stringify(updatedUser));
        localStorage.setItem('x5_credits', String(updatedUser.credits || 0));
    };

    const handleLogout = () => {
        supabase.auth.signOut().catch(() => { });
        localStorage.removeItem('x5_user');
        localStorage.removeItem('x5_credits');
        localStorage.removeItem('x5_usage');
        setUser(GUEST_USER);
        setCurrentView('home');
    };

    const checkUsageAndProceed = (tier: 'standard' | 'pro', cost: number = 5): boolean => {
        // Only CHECK if user has enough credits - do NOT deduct here!
        if ((user.credits || 0) < cost) {
            showToast(`Недостаточно кредитов! Нужно: ${cost}, у вас: ${user.credits || 0}`, 'warning');
            return false;
        }
        return true;
    };

    // New function to actually deduct credits AFTER successful generation
    const deductCredits = async (cost: number) => {
        const newAmount = (user.credits || 0) - cost;
        updateCredits(newAmount);

        // Atomic deduction via Supabase RPC
        if (user.id && user.id !== 'guest') {
            try {
                const { error } = await supabase.rpc('deduct_credits', { user_id: user.id, cost });
                if (error) throw error;
            } catch (e) {
                console.error("Failed to sync credits", e);
                updateCredits((user.credits || 0));
                showToast("Ошибка списания кредитов", "error");
            }
        }
    };

    const updateCredits = (newAmount: number) => {
        const updatedUser = { ...user, credits: newAmount };
        setUser(updatedUser);
        localStorage.setItem('x5_credits', newAmount.toString());
        localStorage.setItem('x5_user', JSON.stringify(updatedUser));
    };

    const handleRestoreHistory = (item: HistoryItem) => {
        const dataToRestore = item.content || item.prompt || '';
        if (!dataToRestore) return;
        setInitialPrompt(dataToRestore);

        switch (item.type) {
            case 'contract': setCurrentView('contract'); break;
            case 'design': setCurrentView('design'); break;
            case 'photo': setCurrentView('photo'); break;
            case 'video': setCurrentView('video_gen'); break;
            default: setCurrentView('home');
        }
    };

    const handleInitiateCoursePurchase = async (course: Course) => {
        // Проверка: уже куплен?
        if (user.purchasedCourseIds?.includes(course.id)) {
            showToast("Курс уже куплен", "info");
            return;
        }

        // Проверка кредитов
        if (user.credits >= course.price) {
            const confirmed = await confirm({
                title: `Купить курс?`,
                message: `"${course.title}"`,
                type: 'credits',
                creditCost: course.price,
                userCredits: user.credits,
                confirmText: 'Купить',
                cancelText: 'Отмена'
            });

            if (confirmed) {
                const newCredits = user.credits - course.price;
                const newPurchases = [...(user.purchasedCourseIds || []), course.id];

                const updatedUser = {
                    ...user,
                    credits: newCredits,
                    purchasedCourseIds: newPurchases
                };

                setUser(updatedUser);
                localStorage.setItem('x5_user', JSON.stringify(updatedUser));
                localStorage.setItem('x5_credits', newCredits.toString());

                // Atomic credits deduction + save purchase via Supabase
                try {
                    await supabase.rpc('deduct_credits', { user_id: user.id, cost: course.price });
                    await supabase.from('profiles').update({
                        purchased_course_ids: newPurchases
                    }).eq('id', user.id);
                    showToast("Курс куплен!", "success");
                } catch (err) {
                    console.error("Error saving purchase", err);
                    showToast("Ошибка сохранения, но курс доступен", "warning");
                }

                // Show success logic
                setPendingCourse(course);
                setCurrentView('success');
            }
        } else {
            // Not enough credits
            const goToPaywall = await confirm({
                title: "Недостаточно кредитов",
                message: `Нужно ${course.price} кредитов, у вас ${user.credits}. Пополнить баланс?`,
                type: 'credits',
                creditCost: course.price,
                userCredits: user.credits,
                confirmText: 'Пополнить',
                cancelText: 'Отмена'
            });

            if (goToPaywall) {
                setCurrentView('paywall');
            }
        }
    };

    const handleCoursePurchaseSuccess = async () => {
        if (user && pendingCourse) {
            const newPurchases = [...(user.purchasedCourseIds || []), pendingCourse.id];
            const updatedUser: User = { ...user, purchasedCourseIds: newPurchases };
            setUser(updatedUser);
            localStorage.setItem('x5_user', JSON.stringify(updatedUser));
            try {
                await supabase.from('profiles').update({ purchased_course_ids: newPurchases }).eq('id', user.id);
            } catch (e) { console.error("Failed to save purchase online", e); }
            setPendingCourse(null);
            setCurrentView('success');
        }
    };

    const handleGeneralPaymentSuccess = () => {
        const updatedUser: User = {
            ...user,
            credits: (user.credits || 0) + 1000,
            plan: 'pro'
        };
        setUser(updatedUser);
        localStorage.setItem('x5_credits', updatedUser.credits.toString());
        localStorage.setItem('x5_user', JSON.stringify(updatedUser));
        setCurrentView('success');
    };

    return (
        <>
            <div
                className="relative w-full h-[100dvh] overflow-hidden text-slate-800 select-none font-sans flex"
                onTouchStart={onTouchStart}
                onTouchMove={onTouchMove}
                onTouchEnd={onTouchEnd}
            >
                <Background view={currentView} />

                {/* DESKTOP SIDEBAR - FIXED */}
                <div className="hidden md:flex w-72 flex-col glass-panel m-4 rounded-[32px] border border-white/40 overflow-y-auto relative z-50 no-scrollbar bg-white/70 backdrop-blur-xl shadow-2xl">
                    <div className="p-8 pb-4 flex-1">
                        <div className="flex items-center gap-3 mb-10">
                            <div className="w-10 h-10 rounded-xl bg-slate-900 text-white flex items-center justify-center shadow-lg">
                                <span className="font-bold text-lg">X5</span>
                            </div>
                            <span className="text-xl font-extrabold text-slate-900 tracking-tight">OS</span>
                        </div>

                        <div className="space-y-3">
                            <button onClick={() => handleNavigate('home')} className={`w-full p-4 rounded-[20px] flex items-center gap-4 text-left transition-all duration-300 group ${currentView === 'home' ? 'bg-slate-900 text-white shadow-xl shadow-slate-900/10 scale-[1.02]' : 'hover:bg-white/60 text-slate-600'}`}>
                                <Home size={20} strokeWidth={currentView === 'home' ? 2.5 : 2} className={currentView === 'home' ? 'text-white' : 'text-slate-400 group-hover:text-slate-600'} />
                                <span className="font-bold text-sm">Главная</span>
                            </button>

                            <button onClick={() => handleNavigate('courses')} className={`w-full p-4 rounded-[20px] flex items-center gap-4 text-left transition-all duration-300 group ${currentView === 'courses' ? 'bg-slate-900 text-white shadow-xl shadow-slate-900/10 scale-[1.02]' : 'hover:bg-white/60 text-slate-600'}`}>
                                <GraduationCap size={20} strokeWidth={currentView === 'courses' ? 2.5 : 2} className={currentView === 'courses' ? 'text-white' : 'text-slate-400 group-hover:text-slate-600'} />
                                <span className="font-bold text-sm">Академия</span>
                            </button>

                            <button onClick={() => handleNavigate('hire')} className={`w-full p-4 rounded-[20px] flex items-center gap-4 text-left transition-all duration-300 group ${currentView === 'hire' ? 'bg-slate-900 text-white shadow-xl shadow-slate-900/10 scale-[1.02]' : 'hover:bg-white/60 text-slate-600'}`}>
                                <Briefcase size={20} strokeWidth={currentView === 'hire' ? 2.5 : 2} className={currentView === 'hire' ? 'text-white' : 'text-slate-400 group-hover:text-slate-600'} />
