                                        return (
                                            <motion.button
                                                key={view}
                                                whileTap={{ scale: 0.85 }}
                                                onClick={() => handleNavigate(view as any)}
                                                className="relative flex flex-col items-center justify-center gap-0.5 py-2 px-3 rounded-[16px]"
