                                                        className="absolute inset-0 rounded-[16px]"
                                                        style={{
                                                            background: 'rgba(255,255,255,0.35)',
                                                            boxShadow: '0 2px 12px rgba(0,0,0,0.08), inset 0 1px 0 rgba(255,255,255,0.5)',
                                                        }}
                                                        transition={{ type: 'spring', damping: 28, stiffness: 320 }}
                                                    />
                                                )}
                                                <Icon
                                                    size={21}
                                                    className={`relative z-10 transition-colors duration-200 ${
                                                        isActive ? 'text-slate-900' : 'text-slate-400'
                                                    }`}
                                                    strokeWidth={isActive ? 2.2 : 1.8}
                                                />
                                                <span className={`text-[9px] font-semibold relative z-10 transition-colors duration-200 ${
                                                    isActive ? 'text-slate-900' : 'text-slate-400'
                                                }`}>{label}</span>
                                            </motion.button>
                                        );
                                    })}
                                </div>
                            </div>
                        </motion.div>
                    )}

                </div>
            </div>

            {/* OVERLAYS - OUTSIDE of the swipe container to prevent event capturing */}
            {currentView === 'paywall' && (
                <PaywallView
                    language={language}
                    onClose={() => handleNavigate('profile')}
                    onBuy={() => console.log("Web payment triggered (PaywallView)")}
                    platform={platform}
                    user={user}
                />
            )}

            {currentView === 'course_editor' && (
                <CourseEditorView
                    user={user}
                    onBack={() => handleNavigate('courses')}
                    onNavigate={handleNavigate}
                    initialPrompt={navigationPayload ? JSON.stringify(navigationPayload) : undefined}
                />
            )}
        </>
    );
}

export default App;

