import React, { useState, useEffect, useCallback, memo, useRef } from 'react';
import { Home, GraduationCap, User as UserIcon, MessageCircle, LogOut, Zap, BarChart2, Briefcase, MessageSquare, Plus, Sparkles, Grid3X3 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { DesignView } from './views/DesignView';
import { PhotoView } from './views/PhotoView';
import { ContractView } from './views/ContractView';
import { VideoCreativeView } from './views/VideoCreativeView';
import { ProjectsHistoryView } from './views/ProjectsHistoryView';
import { CoursesView } from './views/CoursesView';
import { MyCoursesView } from './views/MyCoursesView';
import { ProfileView } from './views/ProfileView';
import { HomeView } from './views/HomeView';
import { AdminView } from './views/AdminView';
import { AdminApiKeyView } from './views/AdminApiKeyView';
import { AllTechView } from './views/AllTechView';
import { LanguageView } from './views/LanguageView';
import { ChatView } from './views/ChatView';
import { InstagramView } from './views/InstagramView';
import { VideoGenView } from './views/VideoGenView';
import { SuccessView } from './views/SuccessView';
import { MockPaymentView } from './views/MockPaymentView';
import { AnalyticsView } from './views/AnalyticsView';
import { HireView } from './views/HireView';
import { ChatsListView } from './views/ChatsListView';
import { PaywallView } from './views/PaywallView';
import { CourseEditorView } from './views/CourseEditorView';
import { WhatsAppBotView } from './views/WhatsAppBotView';
import { RedirectView } from './views/RedirectView';
import { BusinessLandingView } from './views/BusinessLandingView';
import { CRMView } from './views/CRMView';
import { ViewState, User, Language, HistoryItem, AppConfig, ChatMessage, UsageState, Course, Platform, Specialist } from './types';
import { supabase } from './supabase';
import { detectPlatform } from './utils/platformUtils';
import { t } from './services/translations';
import { useToast } from './components/Toast';
import { useConfirmDialog } from './components/ConfirmDialog';
import { startPresenceTracking, stopPresenceTracking } from './services/presenceService';
import { showNotification } from './services/notificationService';

const defaultConfig: AppConfig = {
    photo: true,
    design: true,
    contract: true,
    video: true,
    courses: true
};

const MAIN_TABS: ViewState[] = ['home', 'courses', 'hire', 'chats_list', 'profile'];

const GUEST_USER: User = {
    id: 'guest',
    name: 'Гость',
    isGuest: true,
    plan: 'free',
    credits: 0
};

type NativeAuthProvider = 'apple' | 'google' | 'email';

type NativeAuthResultPayload = {
    success: boolean;
    provider?: NativeAuthProvider;
    accessToken?: string;
    refreshToken?: string;
    error?: string;
    canceled?: boolean;
    cancelled?: boolean;
};

type NativeAuthBootstrapPayload = {
    id: string;
    name?: string;
    email?: string;
    avatar?: string;
    isGuest?: boolean;
    plan?: 'free' | 'pro' | 'black';
    credits?: number;
    purchasedCourseIds?: string[];
    subscriptionDate?: string;
    subscriptionEndDate?: string;
    subscriptionType?: 'monthly' | 'yearly';
    purchaseHistory?: any[];
};

type NativePaymentResultPayload = {
    success: boolean;
    productId?: string;
    canceled?: boolean;
    cancelled?: boolean;
    error?: string;
    isActive?: boolean;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
    typeof value === 'object' && value !== null;

const parseEventDetail = (rawDetail: unknown): unknown => {
    if (typeof rawDetail !== 'string') return rawDetail;
    try {
        return JSON.parse(rawDetail);
    } catch {
        return null;
    }
};

const parseNativeAuthResult = (rawDetail: unknown): NativeAuthResultPayload | null => {
    const detail = parseEventDetail(rawDetail);
    if (!isRecord(detail)) return null;
    if (typeof detail.success !== 'boolean') return null;

    if (
        detail.provider !== undefined &&
        detail.provider !== 'apple' &&
        detail.provider !== 'google' &&
        detail.provider !== 'email'
    ) {
        return null;
    }

    if (detail.accessToken !== undefined && typeof detail.accessToken !== 'string') return null;
    if (detail.refreshToken !== undefined && typeof detail.refreshToken !== 'string') return null;
    if (detail.error !== undefined && typeof detail.error !== 'string') return null;
    if (detail.canceled !== undefined && typeof detail.canceled !== 'boolean') return null;
    if (detail.cancelled !== undefined && typeof detail.cancelled !== 'boolean') return null;

    return detail as NativeAuthResultPayload;
};

const parseNativeAuthBootstrap = (rawDetail: unknown): NativeAuthBootstrapPayload | null => {
    const detail = parseEventDetail(rawDetail);
    if (!isRecord(detail)) return null;
    if (typeof detail.id !== 'string' || !detail.id) return null;
    if (detail.name !== undefined && typeof detail.name !== 'string') return null;
    if (detail.email !== undefined && typeof detail.email !== 'string') return null;
    if (detail.avatar !== undefined && typeof detail.avatar !== 'string') return null;
    if (detail.isGuest !== undefined && typeof detail.isGuest !== 'boolean') return null;
    if (detail.credits !== undefined && typeof detail.credits !== 'number') return null;
    if (detail.purchasedCourseIds !== undefined && !Array.isArray(detail.purchasedCourseIds)) return null;
    return detail as NativeAuthBootstrapPayload;
};

const parseNativePaymentResult = (rawDetail: unknown): NativePaymentResultPayload | null => {
    const detail = parseEventDetail(rawDetail);
    if (!isRecord(detail)) return null;
    if (typeof detail.success !== 'boolean') return null;
    if (detail.productId !== undefined && typeof detail.productId !== 'string') return null;
    if (detail.error !== undefined && typeof detail.error !== 'string') return null;
    if (detail.canceled !== undefined && typeof detail.canceled !== 'boolean') return null;
    if (detail.cancelled !== undefined && typeof detail.cancelled !== 'boolean') return null;
    if (detail.isActive !== undefined && typeof detail.isActive !== 'boolean') return null;
    return detail as NativePaymentResultPayload;
};

const Background = memo(({ view }: { view: ViewState }) => {
    const isHome = view === 'home';
    return (
        <div className={`liquid-bg ${isHome ? 'orange-theme' : ''}`}>
            <div className={`liquid-blob ${isHome ? 'blob-orange-1' : 'blob-1'}`}></div>
            <div className={`liquid-blob ${isHome ? 'blob-orange-2' : 'blob-2'}`}></div>
            <div className={`liquid-blob ${isHome ? 'blob-orange-3' : 'blob-3'}`}></div>
        </div>
    );
});

function App() {
    const { showToast } = useToast();
    const { confirm } = useConfirmDialog();

    // Check for redirect URL (/r/:shortCode)
    const [redirectShortCode, setRedirectShortCode] = useState<string | null>(() => {
        const path = window.location.pathname;
        if (path.startsWith('/r/')) {
            return path.substring(3); // Extract shortCode
        }
        return null;
    });

    // Check for invite URL (/invite/:code)
    const [inviteCode, setInviteCode] = useState<string | null>(() => {
        const path = window.location.pathname;
        if (path.startsWith('/invite/')) {
            return path.substring(8); // Extract invite code
        }
        return null;
    });

    // If we have a redirect shortCode, render the redirect view
    if (redirectShortCode) {
        return <RedirectView shortCode={redirectShortCode} />;
    }

    // Store toast function in ref for use in window callbacks
    const showToastRef = useRef(showToast);
    useEffect(() => {
        showToastRef.current = showToast;
    }, [showToast]);

    const [user, setUser] = useState<User>(() => {
        const saved = localStorage.getItem('x5_user');
        if (saved) {
            try {
                const parsed = JSON.parse(saved);
                return { ...parsed, plan: parsed.plan || 'free', credits: parsed.credits || 0 };
            } catch (e) { }
        }
        return GUEST_USER;
    });

    // Ref to always have current user in callbacks (fixes stale closure)
    const userRef = useRef(user);
    useEffect(() => {
        userRef.current = user;
    }, [user]);
    const nativeAuthLockUntilRef = useRef(0);
    const googleNativeRetryRef = useRef(0);

    const [loading, setLoading] = useState(true);
    const [currentView, setCurrentView] = useState<ViewState>('home');
    const [initialPrompt, setInitialPrompt] = useState<string>('');
    const [transitionClass, setTransitionClass] = useState('animate-fade-in');
    const [navigationPayload, setNavigationPayload] = useState<any>(null);
    const [isTabBarVisible, setIsTabBarVisible] = useState(true);
    const [tabBarHiddenByScroll, setTabBarHiddenByScroll] = useState(false);
    const lastScrollY = React.useRef(0);

    const [platform, setPlatform] = useState<Platform>(() => {
        const override = localStorage.getItem('x5_platform_override') as Platform | null;
        return override || detectPlatform();
    });

    useEffect(() => {
        const detected = detectPlatform();
        const override = localStorage.getItem('x5_platform_override') as Platform | null;
        const nextPlatform = override || detected;
        setPlatform((prev) => (prev === nextPlatform ? prev : nextPlatform));
    }, []);

    const handlePlatformChange = (newPlatform: Platform) => {
        setPlatform(newPlatform);
        localStorage.setItem('x5_platform_override', newPlatform);
    };

    const [language, setLanguage] = useState<Language>(() => {
        const saved = localStorage.getItem('x5_language');
        return (saved as Language) || 'ru';
    });

    const [usage, setUsage] = useState<UsageState>({ guestStandardCount: 0, proCount: 0 });
    const [config, setConfig] = useState<AppConfig>(() => {
        const saved = localStorage.getItem('x5_config');
        return saved ? JSON.parse(saved) : defaultConfig;
    });

    const [pendingCourse, setPendingCourse] = useState<Course | null>(null);

    // CHAT STATE
    const [activeSpecialist, setActiveSpecialist] = useState<Specialist | null>(null);
    const [chatsList, setChatsList] = useState<any[]>([]);

    // Hide TabBar on scroll down, show on scroll up
    useEffect(() => {
        let ticking = false;

        const handleScroll = () => {
            if (!ticking) {
                window.requestAnimationFrame(() => {
                    const currentScrollY = window.scrollY;
                    const scrollingDown = currentScrollY > lastScrollY.current && currentScrollY > 50;
                    const scrollingUp = currentScrollY < lastScrollY.current;

                    if (scrollingDown) {
                        setTabBarHiddenByScroll(true);
                    } else if (scrollingUp) {
                        setTabBarHiddenByScroll(false);
                    }

                    lastScrollY.current = currentScrollY;
                    ticking = false;
                });
                ticking = true;
            }
        };

        // Also listen to scroll events on scrollable containers
        const handleElementScroll = (e: Event) => {
            const target = e.target as HTMLElement;
            if (!target || !target.scrollTop) return;

            const currentScrollY = target.scrollTop;
            const prevScrollY = (target as any).__prevScrollY || 0;

            if (currentScrollY > prevScrollY && currentScrollY > 50) {
                setTabBarHiddenByScroll(true);
            } else if (currentScrollY < prevScrollY) {
                setTabBarHiddenByScroll(false);
            }

            (target as any).__prevScrollY = currentScrollY;
        };

        window.addEventListener('scroll', handleScroll, { passive: true });
        document.addEventListener('scroll', handleElementScroll, { passive: true, capture: true });

        return () => {
            window.removeEventListener('scroll', handleScroll);
            document.removeEventListener('scroll', handleElementScroll, true);
        };
    }, []);

    // Push notifications are handled by Expo native layer
    // Web notifications will be handled via Supabase realtime

    // If we're processing an invite, show loading
    if (inviteCode && !user.isGuest && loading) {
        return (
            <div className="w-full h-[100dvh] bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="bg-white rounded-[32px] p-8 shadow-2xl max-w-sm w-full mx-4 text-center">
