        const handleNativeAuth = async (e: Event) => {
            const detail = parseNativeAuthResult((e as CustomEvent).detail);
            if (!detail) return;
            // Old native build dispatches appleSignInResult for non-Apple providers too.
            // Ignore duplicated non-Apple payloads from that channel.
            if (e.type === 'appleSignInResult' && detail.provider && detail.provider !== 'apple') return;

            const applyNativeAuthUser = async (accessToken: string) => {
                try {
                    const { data: authData, error: authError } = await supabase.auth.getUser(accessToken);
                    if (authError || !authData?.user) return;

                    const authUser = authData.user;
                    const { data: profile } = await supabase
