                    localStorage.setItem('x5_credits', String(forcedUser.credits || 0));
                } catch {
                    // no-op fallback
                }
            };

            if (detail.success && detail.accessToken) {
                if (detail.provider === 'google') {
                    googleNativeRetryRef.current = 0;
                }
                nativeAuthLockUntilRef.current = Date.now() + 10_000;
                try {
                    if (detail.refreshToken) {
